44	#define CVCUDA_SIFT_INTERNAL_DATA_CHECK(data)                                              \
45	    if (!data)                                                                             \
46	    {                                                                                      \
47	        throw nvcv::Exception(nvcv::Status::ERROR_INTERNAL, "Invalid SIFT internal data"); \
48	    }
