50	constexpr NVCVBorderType        kBorderGauss{NVCV_BORDER_REFLECT101}; // default border for Gaussian operation
51	constexpr NVCVBorderType        kBorderInterp{NVCV_BORDER_REPLICATE}; // default border for interpolation
52	constexpr NVCVInterpolationType kInterpUp{NVCV_INTERP_LINEAR};        // default interpolation for up scaling
53	
54	constexpr float kMinSigma              = 0.01f;      // minimum sigma to be used as base sigma
55	constexpr float kPrevSigma             = 0.5f;       // previous sigma before base image
56	constexpr int   kMaxKernelSize         = 59;         // maximum Gaussian kernel size
57	constexpr int   kDescriptorOctaveBatch = 2;          // octaves handled by one descriptor launch
58	constexpr int2  kBorderSize            = int2{5, 5}; // ignore keypoints close to the border
59	constexpr int   kMaxInterpolationSteps = 5;          // max. steps of keypoint interpolation before failure
60	
61	constexpr float kRadiansToDegrees   = 180.f / M_PI;           // convert from radians to degrees
62	constexpr float kDegreesToRadians   = M_PI / 180.f;           // convert from degrees to radians
63	constexpr float kOrientationSigma   = 1.5f;                   // sigma used for angle orientation computation
64	constexpr float kOrientationRadius  = 3 * kOrientationSigma;  // radius of the region to compute angle orientation
65	constexpr float kHistogramPeakRatio = 0.8f;                   // histogram peak ratio to create new feature
66	constexpr int   kHistogramBins      = 36;                     // number of histogram bins, impacts register pressure
67	constexpr float kAngleToBin         = kHistogramBins / 360.f; // angle in degrees to a bin index in histogram
68	constexpr float kBinToAngle         = 360.f / kHistogramBins; // bin index to angle in degrees
69	
70	constexpr int   kDescOriRadius     = 3;                                // radius for orientation in descriptor hist.
71	constexpr int   kDescWidth         = 4;                                // width of the descriptor
72	constexpr int   kDescHistBins      = 8;                                // number of bins per histogram in descriptor
73	constexpr float kAngleToDescBin    = kDescHistBins / 360.f;            // angle in degrees to a desc. hist. bin index
74	constexpr float kDescWeightScale   = -2.f / (kDescWidth * kDescWidth); // weight scale in descriptor histogram
75	constexpr float kDescWidthToRadius = M_SQRT2 * (kDescWidth + 1) * .5f; // convert from histogram width to radius
76	constexpr int   kDescMaxRadius     = 51;                               // maximum radius considering max. initSigma=2.4
77	constexpr float kDescHistPeakRatio = .2f;                              // maximum allowed magnitude in descriptor
78	constexpr int   kDescF32toU8Ratio  = 512;                              // convert desc. value from float to uint8_t
79	
80	constexpr int kDescSize          = kDescWidth * kDescWidth * kDescHistBins;                   // desc. size (=128B)
81	constexpr int kDescHistTotalBins = (kDescWidth + 2) * (kDescWidth + 2) * (kDescHistBins + 2); // desc. hist. size
