83	// Tensor wrap for LNHWC tensors with C inside its type
84	template<typename T>
85	using TensorWrapLNHW = cuda::TensorWrap32<T, -1, -1, -1, sizeof(T)>;
86	
87	// Border wrap for LNHWC tensors using the corresponding tensor wrap
88	template<typename T>
89	using BorderWrapLNHW = cuda::BorderWrap<TensorWrapLNHW<T>, kBorderGauss, false, false, true, true>;
90	
91	// Tensor wrap for descriptor has 2 compile-time strides: per 128B descriptor and per 1B within descriptor
92	using TensorWrapForDescriptor = cuda::TensorWrap32<uint8_t, -1, kDescSize * sizeof(uint8_t), sizeof(uint8_t)>;
