96	// Function to get a view from a tensor parent data with given shape
97	inline __host__ nvcv::Tensor GetViewFrom(const nvcv::TensorDataStridedCuda  &parentData,
98	                                         const nvcv::TensorShape::ShapeType &viewShape)
99	{
100	    // Get tensor data and create a view of it with given shape instead of its original shape
101	    NVCVTensorData viewData = parentData.cdata();
102	
103	    NVCV_ASSERT(viewData.rank == viewShape.rank());
104	
105	    for (int r = 0; r < viewData.rank; r++)
106	    {
107	        NVCV_ASSERT(viewData.shape[r] >= viewShape[r]);
108	
109	        viewData.shape[r] = viewShape[r];
110	    }
111	
112	    return nvcv::TensorWrapData(nvcv::TensorData{viewData});
113	}
