115	// Function to compute number of octaves for an WxH image with W=width and H=height
116	inline __host__ int ComputeNumberOfOctaves(int width, int height)
117	{
118	    return std::round((std::log2(std::min(width, height))) - 2) + 1;
119	}
120	
121	// Compute Gaussian filter kernel size for a given sigma
122	inline __host__ int ComputeGaussianKernelSize(float sigma)
123	{
124	    return cuda::min(cuda::round<int>(sigma * 8 + 1) | 1, kMaxKernelSize);
125	}
