129	// Direct (no scale) copy a source 3-rank NHW tensor into a destination 4-rank LNHW tensor
130	template<class SrcWrapper>
131	__global__ void Copy(TensorWrapLNHW<float> dst, SrcWrapper src, int3 srcShape)
132	{
133	    int3 srcCoord = cuda::StaticCast<int>(blockIdx * blockDim + threadIdx);
134	
135	    if (srcCoord.x < srcShape.x && srcCoord.y < srcShape.y && srcCoord.z < srcShape.z)
136	    {
137	        int4 dstCoord{srcCoord.x, srcCoord.y, srcCoord.z, 0};
138	
139	        dst[dstCoord] = src[srcCoord];
140	    }
141	}
142	
143	// Expand (2x upscale) copy a source 3-rank NHW tensor into a destination 4-rank LNHW tensor
144	template<class SrcWrapper>
145	__global__ void UpCopy(TensorWrapLNHW<float> dst, SrcWrapper src, int3 dstShape)
146	{
147	    int3 coord = cuda::StaticCast<int>(blockIdx * blockDim + threadIdx);
148	
149	    if (coord.x < dstShape.x && coord.y < dstShape.y && coord.z < dstShape.z)
150	    {
151	        int4   dstCoord{coord.x, coord.y, coord.z, 0};
152	        float3 srcCoord{0, 0, (float)coord.z};
153	
154	        srcCoord.x = (coord.x + .5f) * .5f - .5f;
155	        srcCoord.y = (coord.y + .5f) * .5f - .5f;
156	
157	        dst[dstCoord] = src[srcCoord];
158	    }
159	}
