161	// Contract (2x downscale) copy a source 4-rank LNHW tensor into a destination 4-rank LNHW tensor
162	template<class SrcWrapper>
163	__global__ void DownCopy(TensorWrapLNHW<float> dst, SrcWrapper src, int3 dstShape, int srcLayer)
164	{
165	    int3 coord = cuda::StaticCast<int>(blockIdx * blockDim + threadIdx);
166	
167	    if (coord.x < dstShape.x && coord.y < dstShape.y && coord.z < dstShape.z)
168	    {
169	        int4 dstCoord{coord.x, coord.y, coord.z, 0};
170	        int4 srcCoord{coord.x * 2, coord.y * 2, coord.z, srcLayer};
171	
172	        dst[dstCoord] = src[srcCoord];
173	    }
174	}
