176	// Compute Gaussian and DoG (Difference of Gaussians) SIFT pyramids of current octave and layer
177	template<int BW, int BH>
178	__global__ void DoComputePyramids(BorderWrapLNHW<float> prevGauss, TensorWrapLNHW<float> currGauss,
179	                                  TensorWrapLNHW<float> currDoG, int3 currShape, int currLayer, int currKernelSize,
180	                                  cuda::math::Vector<float, kMaxKernelSize> gaussSepKernel)
181	{
182	    // Based on kMaxKernelSize = 59 and kDataTile = 32x32x1. The launch reserves only the space required by the
183	    // current Gaussian kernel, up to this maximum.
184	    // Registers used: 40
185	    // SMEM usage (max. 48KB): 44772 B = ((32 + 59) * (32 + 59)) * 4 + (32 * (32 + 59)) * 4
186	    // CMEM usage (max. 4KB): 688 B = 59 * 4 + 4 + 4 + 4 + 4 * 3 + (4 * 3 + 8) * 2 + (4 * 3 + 4 * 2 + 8) + (360)
187	
188	    extern __shared__ float sharedData[];
189	
190	    const int gaussInWidth = BW + currKernelSize;
191	    float    *gaussInData  = sharedData;
192	    float    *gaussOutData = gaussInData + (BH + currKernelSize) * gaussInWidth;
193	
194	    // The input row stride follows the current kernel support instead of the maximum supported one.
195	    cuda::TensorWrap32<float, -1, sizeof(float)>                 gaussIn(gaussInData,
196	                                                                         static_cast<int32_t>(gaussInWidth * sizeof(float)));
197	    cuda::TensorWrap32<float, BW * sizeof(float), sizeof(float)> gaussOut(gaussOutData);
198	
199	    int half = currKernelSize / 2; // i.e. the halo or support data outside block to compute Gaussian filter
200	
201	    int2 tc; // thread (local) coordinates to access SMEM data
202	    int2 pc; // previous (local) coordinates to access SMEM data (previous of thread)
203	    int2 mc; // mirrored (local) coordinates to access SMEM data (mirror of previous)
204	
205	    int4 gc{0, 0, (int)blockIdx.z, cuda::max(0, currLayer - 1)}; // current (global) coordinates for GMEM data
206	
207	    float result; // temporary Gaussian filtering result
208	
209	    // Threads are defined in a 1D block dimension to be just a count of threads to run this kernel
210	    // First loop uses all threads reshaping them to 2D to load block with halo from global memory (GMEM) into SMEM
211	    for (int ti = threadIdx.x; ti < (BW + half * 2) * (BH + half * 2); ti += blockDim.x)
212	    {
213	        tc.x = ti % (BW + half * 2);
214	        tc.y = ti / (BW + half * 2);
215	        gc.x = blockIdx.x * BW - half + tc.x;
216	        gc.y = blockIdx.y * BH - half + tc.y;
217	
218	        // The prevGauss is a border wrap allowing access to halo outside image with proper border treatment
219	        gaussIn[tc] = prevGauss[gc];
220	    }
221	
222	    // Second loop runs all threads in 2D to zero out the block with halo in height for intermediary Gaussian output
223	    for (int ti = threadIdx.x; ti < BW * (BH + half * 2); ti += blockDim.x)
224	    {
225	        tc.x = ti % BW;
226	        tc.y = ti / BW;
227	
228	        gaussOut[tc] = 0.f;
229	    }
230	
231	    __syncthreads(); // wait for the input Gaussian data to be loaded and intermediary Gaussian output to be zeroed
232	
233	    // SIFT Gaussian pyramid has resolution levels as octaves with scale-space layers, where the first octave
234	    // only stores one layer as the base image (octave=0, layer=0) and all next octaves do Gaussian filtering.
235	    // [ O=0: [ L=0: base image ] O=1: [ L=0: Gaussian of O=0 L=0; L=1: Gaussian of O=1 L=0; ... ]
236	    //   O=2: [ L=0: copy of O=1 L=numOctaveLayers; L=1: Gaussian of O=2 L=0; ... ] ... ] <- Gaussian pyramid
237	
238	    // Third loop runs all threads in 2D to compute block with halo in height with intermediary Gaussian output
239	    for (int ti = threadIdx.x; ti < BW * (BH + half * 2); ti += blockDim.x)
240	    {
241	        tc.x = ti % BW;
242	        tc.y = ti / BW;
243	        pc.y = tc.y;
244	        pc.x = tc.x + half;
245	        mc.x = 0;
246	        mc.y = tc.y;
247	
248	        result = gaussIn[pc] * gaussSepKernel[half];
249	
250	        for (int kx = 0; kx < half; ++kx)
251	        {
252	            pc.x = tc.x + kx;
253	            mc.x = tc.x + 2 * half - kx;
254	
255	            result += (gaussIn[pc] + gaussIn[mc]) * gaussSepKernel[kx]; // first separable convolution
256	        }
257	
258	        gaussOut[tc] = result;
259	    }
260	
261	    __syncthreads(); // wait for the intermediary (separable) Gaussian filtering output data to be ready
262	
263	    // SIFT DoG pyramid is the Difference of Gaussians: next layer - current layer; it uses next octave from
264	    // the Gaussian pyramid since it stores the base image without Gaussian in its first octave.
265	    // [ O=0: [ L=0: DoG of GaussianPyr (O=1 L=1) - (O=1 L=0); L=1: DoG of GaussianPyr (O=1 L=2) - (O=1 L=1); ... ]
266	    //   O=1: [ L=0: DoG of GaussianPyr (O=2 L=1) - (O=2 L=0); ... ] ] <- DoG pyramid
267	
268	    // Fourth loop runs threads in 2D to compute final block of Gaussian filter and DoG
269	    for (int ti = threadIdx.x; ti < BW * BH; ti += blockDim.x)
270	    {
271	        tc.x = ti % BW;
272	        tc.y = ti / BW;
273	        gc.x = blockIdx.x * BW + tc.x;
274	        gc.y = blockIdx.y * BH + tc.y;
275	
276	        if (gc.x >= currShape.x || gc.y >= currShape.y)
277	        {
278	            continue;
279	        }
280	
281	        gc.w = currLayer;
282	        pc.x = tc.x;
283	        pc.y = tc.y + half;
284	        mc.x = tc.x;
285	        mc.y = 0;
286	
287	        result = gaussOut[pc] * gaussSepKernel[half];
288	
289	        for (int ky = 0; ky < half; ++ky)
290	        {
291	            pc.y = tc.y + ky;
292	            mc.y = tc.y + 2 * half - ky;
293	
294	            result += (gaussOut[pc] + gaussOut[mc]) * gaussSepKernel[ky]; // second separable convolution
295	        }
296	
297	        currGauss[gc] = result;
298	
299	        if (gc.w > 0)
300	        {
301	            gc.w -= 1;
302	            pc.x = half + tc.x;
303	            pc.y = half + tc.y;
304	
305	            currDoG[gc] = result - gaussIn[pc];
306	        }
307	    }
308	}
