310	// Get adjacent neighbor coordinates of center coordinates and deltas d* with x=col, y=row
311	__forceinline__ __device__ int2 adj(const int2 &center, int dRow, int dCol)
312	{
313	    return int2{center.x + dCol, center.y + dRow};
314	}
315	
316	// Get adjacent neighbor coordinates of center coordinates and deltas d* with x=col, y=row, z=batch, w=layer
317	__forceinline__ __device__ int4 adj(const int4 &center, int dLayer, int dRow, int dCol)
318	{
319	    return int4{center.x + dCol, center.y + dRow, center.z, center.w + dLayer};
320	}
