322	// Compute descriptors, using the Gaussian pyramid, the previously computed angle and feature radius and coordinates
323	__global__ void DoComputeDescriptors(TensorWrapForDescriptor             featDescriptors,
324	                                     cuda::Tensor2DWrap<float4, int32_t> featCoords,
325	                                     cuda::Tensor2DWrap<float3, int32_t> featMetadata,
326	                                     cuda::Tensor1DWrap<int, int32_t>    numFeatures,
327	                                     TensorWrapLNHW<const float> firstGauss, int3 firstShape, int firstOctave,
328	                                     float firstScale, TensorWrapLNHW<const float> secondGauss, int3 secondShape,
329	                                     int secondOctave, float secondScale, bool hasSecondOctave)
330	{
331	    constexpr int BW = (kDescMaxRadius + 1) * 2 + 1; // block width with maximum support radius for descriptor
332	    constexpr int BH = (kDescMaxRadius + 1) * 2 + 1; // block height with maximum support radius for descriptor
333	
334	    // Based on kDescMaxRadius = 51
335	    // Registers usage: 40
336	    // SMEM usage (max. 48KB): 45540 B = ((51 + 1) * 2 + 1) * ((51 + 1) * 2 + 1) * 4 + 360 * 4
337	    // CMEM usage (max. 4KB): 452 B = (4 * 1 + 8) * 3 + 8 + (4 * 3 + 8) * 1 + 4 * 3 + 4 + 4 + (368)
338	    // ! 32 Bytes stack frame
339	
340	    __shared__ float gaussInData[BH * BW];          // Gaussian input data to compute descriptors
341	    __shared__ float histogram[kDescHistTotalBins]; // Histogram with intermediary output for descriptors
342	
343	    // Using TensorWrap with compile-time strides for easy multi-dimensional access of Gaussian data in SMEM
344	    cuda::TensorWrap32<float, BW * sizeof(float), sizeof(float)> gaussIn(&gaussInData[0]);
345	
346	    int featIdx   = blockIdx.x; // each block thru x computes one feature descriptor
347	    int sampleIdx = blockIdx.z; // each block thru z computes one image sample
348	
349	    if (featIdx >= numFeatures[sampleIdx])
350	    {
351	        return; // each kernel invocation handles only valid features
352	    }
353	
354	    float                      *pFeatCoords   = reinterpret_cast<float *>(featCoords.ptr(sampleIdx, featIdx));
355	    TensorWrapLNHW<const float> currGauss     = firstGauss;
356	    int3                        currShape     = firstShape;
357	    float                       unscaleOctave = firstScale;
358	
359	    if (pFeatCoords[2] != firstOctave)
360	    {
361	        if (!hasSecondOctave || pFeatCoords[2] != secondOctave)
362	        {
363	            return;
364	        }
365	
366	        currGauss     = secondGauss;
367	        currShape     = secondShape;
368	        unscaleOctave = secondScale;
369	    }
370	
371	    // The coordinate (x, y) and layer of the feature to compute descriptor from
372	    int2 featCoord{cuda::round<int>(pFeatCoords[0] * unscaleOctave), cuda::round<int>(pFeatCoords[1] * unscaleOctave)};
373	    int  featLayer{cuda::round<int>(pFeatCoords[3])};
374	
375	    // Feature metadata at 2 provides size as diameter that has to be halved and uncaled to get descriptor radius
376	    float *pFeatMetadata = reinterpret_cast<float *>(featMetadata.ptr(sampleIdx, featIdx));
377	    float  histWidth     = kDescOriRadius * (pFeatMetadata[2] * .5f * unscaleOctave);
378	    int    radius        = cuda::round<int>(histWidth * kDescWidthToRadius);
379	
380	    // Clamp radius by maximum allowed radius (impacts SMEM resource usage)
381	    if (radius > kDescMaxRadius)
382	    {
383	        radius    = kDescMaxRadius;
384	        histWidth = kDescMaxRadius / kDescWidthToRadius;
385	    }
386	
387	    // Threads are defined in a 1D block dimension to be just a count of threads to run this kernel
388	    // First loop runs threads reshaping them to 2D block of radius + 1-halo around current feature
389	    for (int ti = threadIdx.x; ti < ((radius + 1) * 2 + 1) * ((radius + 1) * 2 + 1); ti += blockDim.x)
390	    {
391	        int2 tc{ti % ((radius + 1) * 2 + 1), ti / ((radius + 1) * 2 + 1)};
392	        int4 gc{featCoord.x - radius - 1 + tc.x, featCoord.y - radius - 1 + tc.y, sampleIdx, featLayer};
393	
394	        if (gc.x < 0 || gc.x >= currShape.x || gc.y < 0 || gc.y >= currShape.y)
395	        {
396	            continue;
397	        }
398	
399	        gaussIn[tc] = currGauss[gc]; // load from global memory (GMEM) into shared memory (SMEM)
400	    }
401	
402	    // Second loop runs threads to zero out descriptor histogram
403	    for (int ti = threadIdx.x; ti < kDescHistTotalBins; ti += blockDim.x)
404	    {
405	        histogram[ti] = 0.f;
406	    }
407	
408	    float featAngle = 360.f - pFeatMetadata[0]; // feature metadata at zero provides angle
409	
410	    if (cuda::abs(featAngle - 360.f) < 1e-5)
411	    {
412	        featAngle = 0.f;
413	    }
414	
415	    float cos_a = ::cosf(featAngle * kDegreesToRadians) / histWidth;
416	    float sin_a = ::sinf(featAngle * kDegreesToRadians) / histWidth;
417	
418	    __syncthreads(); // wait for the histogram to be zeroed and for the R-tile Gaussian data with 1-halo to be loaded
419	
420	    // Third loop runs threads over radius around feature without 1-halo
421	    for (int ti = threadIdx.x; ti < (radius * 2 + 1) * (radius * 2 + 1); ti += blockDim.x)
422	    {
423	        int j = ti % (radius * 2 + 1) - radius;
424	        int i = ti / (radius * 2 + 1) - radius;
425	
426	        int2 tc{1 + radius + j, 1 + radius + i}; // thread (local) coordinate to access SMEM
427	
428	        if (featCoord.x + j <= 0 || featCoord.x + j >= currShape.x - 1 || featCoord.y + i <= 0
429	            || featCoord.y + i >= currShape.y - 1)
430	        {
431	            continue; // if any neighbor is outside current shape
432	        }
433	
434	        float r_rot  = j * sin_a + i * cos_a;         // rotate row index
435	        float c_rot  = j * cos_a - i * sin_a;         // rotate column index
436	        float weight = r_rot * r_rot + c_rot * c_rot; // weight (squared distance) for vector magnitude
437	
438	        r_rot += kDescWidth / 2 - .5f;
439	        c_rot += kDescWidth / 2 - .5f;
440	        if (r_rot <= -1 || r_rot >= kDescWidth || c_rot <= -1 || c_rot >= kDescWidth)
441	        {
442	            continue; // if normalized row or column index is outside descriptor width
443	        }
444	
445	        int iHist = cuda::round<cuda::RoundMode::DOWN, int>(r_rot); // i index in histogram
446	        int jHist = cuda::round<cuda::RoundMode::DOWN, int>(c_rot); // j index in histogram
447	        r_rot -= iHist;
448	        c_rot -= jHist;
449	
450	        float dx = gaussIn[adj(tc, +0, +1)] - gaussIn[adj(tc, +0, -1)]; // Gaussian delta x
451	        float dy = gaussIn[adj(tc, -1, +0)] - gaussIn[adj(tc, +1, +0)]; // Gaussian delta y
452	
453	        float o_rot = ::atan2f(dy, dx) * kRadiansToDegrees; // rotate orientation in degrees
454	        if (o_rot < 0.f)
455	            o_rot += 360.f;
456	        if (o_rot >= 360.f)
457	            o_rot -= 360.f;
458	        o_rot = (o_rot - featAngle) * kAngleToDescBin;
459	
460	        int bin = cuda::round<cuda::RoundMode::DOWN, int>(o_rot); // rotate index for histogram bin
461	        o_rot -= bin;
462	        if (bin < 0)
463	            bin += kDescHistBins;
464	        if (bin >= kDescHistBins)
465	            bin -= kDescHistBins;
466	
467	        weight = ::exp2f(weight * kDescWeightScale); // weighted scale for vector magnitude
468	
469	        float magnitude = ::sqrtf(dx * dx + dy * dy) * weight; // neighbor vector magnitude
470	
471	        // Vector values to be added to the descriptor histogram
472	        float v_r1     = magnitude * r_rot;
473	        float v_r0     = magnitude - v_r1;
474	        float v_rc11   = v_r1 * c_rot;
475	        float v_rc10   = v_r1 - v_rc11;
476	        float v_rc01   = v_r0 * c_rot;
477	        float v_rc00   = v_r0 - v_rc01;
478	        float v_rco111 = v_rc11 * o_rot;
479	        float v_rco110 = v_rc11 - v_rco111;
480	        float v_rco101 = v_rc10 * o_rot;
481	        float v_rco100 = v_rc10 - v_rco101;
482	        float v_rco011 = v_rc01 * o_rot;
483	        float v_rco010 = v_rc01 - v_rco011;
484	        float v_rco001 = v_rc00 * o_rot;
485	        float v_rco000 = v_rc00 - v_rco001;
486	
487	        int idx = ((iHist + 1) * (kDescWidth + 2) + (jHist + 1)) * (kDescHistBins + 2) + bin;
488	
489	        // Atomic adding to the histogram as other threads may hit same (rotated) location
490	        atomicAdd(&histogram[idx], v_rco000);
491	        atomicAdd(&histogram[idx + 1], v_rco001);
492	        atomicAdd(&histogram[idx + (kDescHistBins + 2)], v_rco010);
493	        atomicAdd(&histogram[idx + (kDescHistBins + 3)], v_rco011);
494	        atomicAdd(&histogram[idx + (kDescWidth + 2) * (kDescHistBins + 2)], v_rco100);
495	        atomicAdd(&histogram[idx + (kDescWidth + 2) * (kDescHistBins + 2) + 1], v_rco101);
496	        atomicAdd(&histogram[idx + (kDescWidth + 3) * (kDescHistBins + 2)], v_rco110);
497	        atomicAdd(&histogram[idx + (kDescWidth + 3) * (kDescHistBins + 2) + 1], v_rco111);
498	    }
499	
500	    __syncthreads(); // wait for the histogram to be written with initial vector values
501	
502	    if (threadIdx.x != 0)
503	    {
504	        return; // at this point only one thread updates and uses the histogram to compute the feature descriptor
505	    }
506	
507	    float norm = 0.f;
508	
509	    // Complete histogram as it is a circular histogram and compute its norm
510	    for (int i = 0; i < kDescWidth; i++)
511	    {
512	        for (int j = 0; j < kDescWidth; j++)
513	        {
514	            int histIdx = ((i + 1) * (kDescWidth + 2) + (j + 1)) * (kDescHistBins + 2);
515	
516	            histogram[histIdx] += histogram[histIdx + kDescHistBins];
517	            histogram[histIdx + 1] += histogram[histIdx + kDescHistBins + 1];
518	
519	            for (int bin = 0; bin < kDescHistBins; bin++)
520	            {
521	                float v = histogram[histIdx + bin];
522	
523	                norm += v * v;
524	            }
525	        }
526	    }
527	
528	    // Hysteresis threshold the histogram by its norm
529	
530	    float histMax = ::sqrtf(norm) * kDescHistPeakRatio;
531	
532	    norm = 0.f;
533	
534	    for (int i = 0; i < kDescWidth; i++)
535	    {
536	        for (int j = 0; j < kDescWidth; j++)
537	        {
538	            int histIdx = ((i + 1) * (kDescWidth + 2) + (j + 1)) * (kDescHistBins + 2);
539	
540	            for (int bin = 0; bin < kDescHistBins; bin++)
541	            {
542	                float v = histogram[histIdx + bin];
543	
544	                v = cuda::min(v, histMax);
545	
546	                norm += v * v;
547	
548	                histogram[histIdx + bin] = v;
549	            }
550	        }
551	    }
552	
553	    // Compute the feature descriptor by using its histogram
554	
555	    norm = kDescF32toU8Ratio / cuda::max(::sqrtf(norm), 1e-5f);
556	
557	    for (int i = 0; i < kDescWidth; i++)
558	    {
559	        for (int j = 0; j < kDescWidth; j++)
560	        {
561	            int histIdx = ((i + 1) * (kDescWidth + 2) + (j + 1)) * (kDescHistBins + 2);
562	
563	            for (int bin = 0; bin < kDescHistBins; bin++)
564	            {
565	                float v = histogram[histIdx + bin];
566	
567	                int descIdx = (i * kDescWidth + j) * kDescHistBins + bin;
568	
569	                *featDescriptors.ptr(sampleIdx, featIdx, descIdx) = cuda::SaturateCast<uint8_t>(v * norm);
570	            }
571	        }
572	    }
573	}
574	
575	// Find extrema (feature coordinates + metadata) using Gaussian + DoG (Difference of Gaussians) pyramids
576	template<int BW, int BH, typename DT>
577	__global__ void DoFindExtrema(cuda::Tensor2DWrap<float4, int32_t> featCoords,
578	                              cuda::Tensor2DWrap<float3, int32_t> featMetadata, int maxCapacity,
579	                              cuda::Tensor1DWrap<int, int32_t> numFeatures, TensorWrapLNHW<const float> currGauss,
580	                              TensorWrapLNHW<const float> currDoG, int3 currShape, int featOctave, float scaleOctave,
581	                              int numOctaveLayers, int thr, float contrastThreshold, float edgeThreshold,
582	                              float initSigma)
583	{
584	    constexpr float kImageScale = 1.f / cuda::TypeTraits<DT>::max; // source images data type scale
585	    constexpr float kDScale1    = kImageScale * .5f;               // first derivative scale
586	    constexpr float kDScale2    = kImageScale;                     // second derivative scale
587	    constexpr float kDScaleC    = kImageScale * .25f;              // cross derivative scale
588	
589	    // Registers usage: 68
590	    // SMEM usage (max. 48KB): 0 B
591	    // CMEM usage (max. 4KB): 488 B = (4 * 1 + 8) * 2 + 4 + 8 + (4 * 3 + 8) * 2 + 4 * 3 + 4 * 7 + (372)
592	    // ! 218072 bytes gmem ! 208 Bytes stack frame
593	
594	    float                           cv;  // central value
595	    cuda::math::Vector<float, 3>    dD;  // derivative distances
596	    cuda::math::Vector<float, 3>    sol; // solver solution
597	    cuda::math::Matrix<float, 3, 3> H;   // Hessian matrix
598	
599	    float hist[kHistogramBins]; // histogram for angle computation
600	
601	    int4 gc{0, 0, (int)blockIdx.z, 0}; // global (at tensor level) coordinate to access global memory (GMEM)
602	
603	    // Threads are defined in a 1D block dimension to be just a count of threads to run this kernel
604	    // A single loop uses all threads reshaping them to 2D block to find extrema in GMEM
605	    for (int ti = threadIdx.x; ti < BW * BH; ti += blockDim.x)
606	    {
607	        gc.x = blockIdx.x * BW + (ti % BW);
608	        gc.y = blockIdx.y * BH + (ti / BW);
609	
610	        if (gc.x < kBorderSize.x || gc.x >= currShape.x - kBorderSize.x || gc.y < kBorderSize.y
611	            || gc.y >= currShape.y - kBorderSize.y)
612	        {
613	            continue;
614	        }
615	
616	        // Loop over central layers within an octave, layer 0 and numOctaveLayers + 1 are for top/bottom neighborhood
617	        for (gc.w = 1; gc.w <= numOctaveLayers; gc.w++)
618	        {
619	            cv = currDoG[gc]; // load central DoG value to test if it is an extremum point
620	
621	            // An extremum point is one that is greater or lower than all its 26 neighbors around it (in a 1-halo):
622	            // 26 = 8 in the same layer + 9 in the layer above + 9 in the layer below
623	            // clang-format off
624	            if (cuda::abs(cv) > thr &&
625	                ((cv > 0 &&
626	                  cv >= currDoG[adj(gc, +0, +0, -1)] && cv >= currDoG[adj(gc, +0, +0, +1)] &&
627	                  cv >= currDoG[adj(gc, +0, -1, -1)] && cv >= currDoG[adj(gc, +0, -1, +0)] &&
628	                  cv >= currDoG[adj(gc, +0, -1, +1)] && cv >= currDoG[adj(gc, +0, +1, -1)] &&
629	                  cv >= currDoG[adj(gc, +0, +1, +0)] && cv >= currDoG[adj(gc, +0, +1, +1)] &&
630	                  cv >= currDoG[adj(gc, +1, +0, +0)] &&
631	                  cv >= currDoG[adj(gc, +1, +0, -1)] && cv >= currDoG[adj(gc, +1, +0, +1)] &&
632	                  cv >= currDoG[adj(gc, +1, -1, -1)] && cv >= currDoG[adj(gc, +1, -1, +0)] &&
633	                  cv >= currDoG[adj(gc, +1, -1, +1)] && cv >= currDoG[adj(gc, +1, +1, -1)] &&
634	                  cv >= currDoG[adj(gc, +1, +1, +0)] && cv >= currDoG[adj(gc, +1, +1, +1)] &&
635	                  cv >= currDoG[adj(gc, -1, +0, +0)] &&
636	                  cv >= currDoG[adj(gc, -1, +0, -1)] && cv >= currDoG[adj(gc, -1, +0, +1)] &&
637	                  cv >= currDoG[adj(gc, -1, -1, -1)] && cv >= currDoG[adj(gc, -1, -1, +0)] &&
638	                  cv >= currDoG[adj(gc, -1, -1, +1)] && cv >= currDoG[adj(gc, -1, +1, -1)] &&
639	                  cv >= currDoG[adj(gc, -1, +1, +0)] && cv >= currDoG[adj(gc, -1, +1, +1)]) ||
640	                 (cv < 0 &&
641	                  cv <= currDoG[adj(gc, +0, +0, -1)] && cv <= currDoG[adj(gc, +0, +0, +1)] &&
642	                  cv <= currDoG[adj(gc, +0, -1, -1)] && cv <= currDoG[adj(gc, +0, -1, +0)] &&
643	                  cv <= currDoG[adj(gc, +0, -1, +1)] && cv <= currDoG[adj(gc, +0, +1, -1)] &&
644	                  cv <= currDoG[adj(gc, +0, +1, +0)] && cv <= currDoG[adj(gc, +0, +1, +1)] &&
645	                  cv <= currDoG[adj(gc, +1, +0, +0)] &&
646	                  cv <= currDoG[adj(gc, +1, +0, -1)] && cv <= currDoG[adj(gc, +1, +0, +1)] &&
647	                  cv <= currDoG[adj(gc, +1, -1, -1)] && cv <= currDoG[adj(gc, +1, -1, +0)] &&
648	                  cv <= currDoG[adj(gc, +1, -1, +1)] && cv <= currDoG[adj(gc, +1, +1, -1)] &&
649	                  cv <= currDoG[adj(gc, +1, +1, +0)] && cv <= currDoG[adj(gc, +1, +1, +1)] &&
650	                  cv <= currDoG[adj(gc, -1, +0, +0)] &&
651	                  cv <= currDoG[adj(gc, -1, +0, -1)] && cv <= currDoG[adj(gc, -1, +0, +1)] &&
652	                  cv <= currDoG[adj(gc, -1, -1, -1)] && cv <= currDoG[adj(gc, -1, -1, +0)] &&
653	                  cv <= currDoG[adj(gc, -1, -1, +1)] && cv <= currDoG[adj(gc, -1, +1, -1)] &&
654	                  cv <= currDoG[adj(gc, -1, +1, +0)] && cv <= currDoG[adj(gc, -1, +1, +1)])))
655	            {
656	                // clang-format on
657	
658	                // If the point at gc is an extrema point, fit (in a least-square sense) a quadratic polynomial to
659	                // the magnitude value around it to localize the scale-space extremum with a resolution higher than
660	                // the sampling density over space and scale.  The fit (done below) uses the derivatives of
661	                // sample-point neighbors and the principal curvatures (Hessian matrix) to solve a linear system
662	                // (using LU decomposition).  It converges when the interpolation step is less than half a pixel.
663	
664	                int4 ic = gc; // to-be interpolated global coordinate
665	
666	                bool converged = false;
667	
668	                for (int i = 0; i < kMaxInterpolationSteps; i++)
669	                {
670	                    // clang-format off
671	                    dD[0] = (currDoG[adj(ic, +0, +0, +1)] - currDoG[adj(ic, +0, +0, -1)]) * kDScale1;
672	                    dD[1] = (currDoG[adj(ic, +0, +1, +0)] - currDoG[adj(ic, +0, -1, +0)]) * kDScale1;
673	                    dD[2] = (currDoG[adj(ic, +1, +0, +0)] - currDoG[adj(ic, -1, +0, +0)]) * kDScale1;
674	
675	                    cv = currDoG[ic];
676	
677	                    H[0][0] = (currDoG[adj(ic, +0, +0, +1)] + currDoG[adj(ic, +0, +0, -1)] - 2 * cv) * kDScale2;
678	                    H[1][1] = (currDoG[adj(ic, +0, +1, +0)] + currDoG[adj(ic, +0, -1, +0)] - 2 * cv) * kDScale2;
679	                    H[2][2] = (currDoG[adj(ic, +1, +0, +0)] + currDoG[adj(ic, -1, +0, +0)] - 2 * cv) * kDScale2;
680	
681	                    H[0][1] = H[1][0] = (currDoG[adj(ic, +0, +1, +1)] - currDoG[adj(ic, +0, +1, -1)] -
682	                                         currDoG[adj(ic, +0, -1, +1)] + currDoG[adj(ic, +0, -1, -1)]) * kDScaleC;
683	                    H[0][2] = H[2][0] = (currDoG[adj(ic, +1, +0, +1)] - currDoG[adj(ic, +1, +0, -1)] -
684	                                         currDoG[adj(ic, -1, +0, +1)] + currDoG[adj(ic, -1, +0, -1)]) * kDScaleC;
685	                    H[1][2] = H[2][1] = (currDoG[adj(ic, +1, +1, +0)] - currDoG[adj(ic, +1, -1, +0)] -
686	                                         currDoG[adj(ic, -1, +1, +0)] + currDoG[adj(ic, -1, -1, +0)]) * kDScaleC;
687	                    // clang-format on
688	
689	                    sol = dD; // since solve_inplace solves a 3x3 linear system H * sol = dD in-place
690	
691	                    if (!cuda::math::solve_inplace(H, sol))
692	                    {
693	                        break; // if there is no solution to the linear system, convergence is not possible
694	                    }
695	
696	                    sol = -sol;
697	
698	                    if (cuda::abs(sol[2]) < 0.5f && cuda::abs(sol[1]) < 0.5f && cuda::abs(sol[0]) < 0.5f)
699	                    {
700	                        converged = true;
701	                        break; // less than half a pixel step means converged
702	                    }
703	
704	                    if (cuda::abs(sol[2]) > cuda::TypeTraits<int>::max / 3.f
705	                        || cuda::abs(sol[1]) > cuda::TypeTraits<int>::max / 3.f
706	                        || cuda::abs(sol[0]) > cuda::TypeTraits<int>::max / 3.f)
707	                    {
708	                        break; // too big a step, convergence is not possible
709	                    }
710	
711	                    ic.x += cuda::round<int>(sol[0]);
712	                    ic.y += cuda::round<int>(sol[1]);
713	                    ic.w += cuda::round<int>(sol[2]);
714	
715	                    if (ic.w < 1 || ic.w > numOctaveLayers || ic.x < kBorderSize.x
716	                        || ic.x >= currShape.x - kBorderSize.x || ic.y < kBorderSize.y
717	                        || ic.y >= currShape.y - kBorderSize.y)
718	                    {
719	                        break; // went outside valid bounds, convergence is not possible
720	                    }
721	                }
722	
723	                if (!converged)
724	                {
725	                    continue; // if not converged, skip this extremum point
726	                }
727	
728	                // Feature score is proportional to the solution of the linear system
729	                float featScore = cuda::abs(cv * kImageScale + cuda::math::dot(dD, sol) * .5f);
730	                if (featScore * numOctaveLayers < contrastThreshold)
731	                {
732	                    continue; // skip features with score below contrast threshold
733	                }
734	
735	                // Compute trace and determinant of the Hessian matrix to avoid strong responses of the Laplacian
736	                // operator (approximated by the DoG) to edges, this uses the edge threshold
737	                float trace       = H[0][0] + H[1][1];
738	                float determinant = H[0][0] * H[1][1] - H[0][1] * H[1][0];
739	                if (determinant <= 0
740	                    || trace * trace * edgeThreshold >= (edgeThreshold + 1) * (edgeThreshold + 1) * determinant)
741	                {
742	                    continue;
743	                }
744	
745	                // Feature radius is proportional to the normalized layer solution and initial sigma
746	                float featRadius = initSigma * ::pow(2, (ic.w + sol[2]) / numOctaveLayers);
747	
748	                // The radius used to compute the histogram for feature angle calculation
749	                int radius = cuda::round<int>(featRadius * kOrientationRadius);
750	
751	                float weightScale = -1.f / (2.f * (featRadius * kOrientationSigma) * (featRadius * kOrientationSigma));
752	
753	                for (int i = 0; i < kHistogramBins; ++i)
754	                {
755	                    hist[i] = 0.f;
756	                }
757	
758	                // Loop the radius around extremum point to compute angle and vector magnitude
759	                for (int i = -radius; i <= radius; i++)
760	                {
761	                    if (ic.y + i <= 0 || ic.y + i >= currShape.y - 1)
762	                    {
763	                        continue;
764	                    }
765	
766	                    for (int j = -radius; j <= radius; j++)
767	                    {
768	                        if (ic.x + j <= 0 || ic.x + j >= currShape.x - 1)
769	                        {
770	                            continue;
771	                        }
772	
773	                        // Compute Gaussian delta x and y using 1-halo neighborhood
774	                        float dx = currGauss[adj(ic, 0, i + 0, j + 1)] - currGauss[adj(ic, 0, i + 0, j - 1)];
775	                        float dy = currGauss[adj(ic, 0, i - 1, j + 0)] - currGauss[adj(ic, 0, i + 1, j + 0)];
776	
777	                        float angle     = ::atan2f(dy, dx) * kRadiansToDegrees;   // angle in degrees
778	                        float weight    = ::exp2f((i * i + j * j) * weightScale); // weighted scale of vector magnitude
779	                        float magnitude = ::sqrtf(dx * dx + dy * dy);             // neighbor vector magnitude
780	
781	                        if (angle < 0.f)
782	                            angle += 360.f;
783	                        if (angle >= 360.f)
784	                            angle -= 360.f;
785	
786	                        int bin = cuda::round<int>(angle * kAngleToBin); // the angle indexes the histogram bin
787	                        bin = (bin >= kHistogramBins ? bin - kHistogramBins : (bin < 0 ? bin + kHistogramBins : bin));
788	
789	                        hist[bin] += weight * magnitude; // store the vector magnitude of the angle bin
790	                    }
791	                }
792	
793	                int   bin       = 0;
794	                float prologue1 = hist[kHistogramBins - 1];
795	                float prologue2 = hist[kHistogramBins - 2];
796	                float center    = hist[bin];
797	                float epilogue1 = hist[bin + 1];
798	                float epilogue2 = hist[bin + 2];
799	                float first     = hist[0];
800	                float second    = hist[1];
801	                do // smooth histogram in-place using loaded prologues and epilogues (plus center, first and second)
802	                {
803	                    hist[bin++]
804	                        = (prologue2 + epilogue2) * 1.f / 16 + (prologue1 + epilogue1) * 4.f / 16 + center * 6.f / 16;
805	
806	                    prologue2 = prologue1;
807	                    prologue1 = center;
808	                    center    = epilogue1;
809	                    epilogue1 = epilogue2;
810	                    epilogue2
811	                        = bin == kHistogramBins - 2 ? first : (bin >= kHistogramBins - 1 ? second : hist[bin + 2]);
812	                }
813	                while (bin < kHistogramBins);
814	
815	                // Compute maximum (peak) value in histogram
816	                float histPeak = hist[0];
817	                for (int i = 1; i < kHistogramBins; ++i)
818	                {
819	                    histPeak = cuda::max(histPeak, hist[i]);
820	                }
821	                histPeak *= kHistogramPeakRatio; // apply a ratio to the histogram peak
822	
823	                int validAngles = 0;
824	
825	                bin       = 0;
826	                prologue1 = hist[kHistogramBins - 1];
827	                center    = hist[bin];
828	                epilogue1 = hist[bin + 1];
829	                first     = hist[0];
830	                do // find valid angles (close to histogram peak) replacing histogram by the valid angles
831	                {
832	                    if (center > prologue1 && center > epilogue1 && center >= histPeak)
833	                    {
834	                        float fbin = bin + .5f * (prologue1 - epilogue1) / (prologue1 - 2 * center + epilogue1);
835	
836	                        fbin = (fbin < 0 ? kHistogramBins + fbin
837	                                         : (fbin >= kHistogramBins ? fbin - kHistogramBins : fbin));
838	
839	                        hist[validAngles++] = 360.f - fbin * kBinToAngle;
840	                    }
841	
842	                    bin++;
843	                    prologue1 = center;
844	                    center    = epilogue1;
845	                    epilogue1 = bin + 1 >= kHistogramBins ? first : hist[bin + 1];
846	                }
847	                while (bin < kHistogramBins);
848	
849	                if (validAngles == 0)
850	                {
851	                    continue; // if there is no valid angle, skip this extremum point
852	                }
853	
854	                int firstFeatIdx = atomicAdd(numFeatures.ptr(ic.z), validAngles);
855	                if (firstFeatIdx >= maxCapacity)
856	                {
857	                    continue; // skip if the feature index is beyond maximum capacity to store features
858	                }
859	
860	                for (int vi = 0; vi < validAngles; ++vi)
861	                {
862	                    if (firstFeatIdx + vi >= maxCapacity)
863	                    {
864	                        break; // skip if the feature index is beyond maximum capacity to store features
865	                    }
866	
867	                    float angle = hist[vi]; // load valid angle stored in the histogram
868	                    if (cuda::abs(angle - 360.f) < 1e-5)
869	                        angle = 0.f;
870	
871	                    // Write the feature coordinate (octave scaled) and metadata in corresponding output tensors
872	                    *featCoords.ptr(ic.z, firstFeatIdx + vi)
873	                        = float4{(ic.x + sol[0]) * scaleOctave, (ic.y + sol[1]) * scaleOctave, (float)featOctave,
874	                                 (ic.w + sol[2])};
875	                    *featMetadata.ptr(ic.z, firstFeatIdx + vi)
876	                        = float3{angle, featScore, featRadius * 2.f * scaleOctave};
877	                }
878	            }
879	        }
880	    }
881	}
