889	// Find SIFT features as extrema keypoints and compute their metadata, DT is the input data type
890	template<typename DT>
891	void SIFT::FindExtrema(const nvcv::TensorDataStridedCuda &featCoordsData,
892	                       const nvcv::TensorDataStridedCuda &featMetadataData,
893	                       const nvcv::TensorDataStridedCuda &featDescriptorsData, int maxCapacity,
894	                       const nvcv::TensorDataStridedCuda &numFeaturesData, int3 currShape, int firstOctave,
895	                       int numOctaves, int numOctaveLayers, float contrastThreshold, float edgeThreshold,
896	                       float initSigma, cudaStream_t stream) const
897	{
898	    constexpr int BW = 32; // data block tile width handled by find extrema kernel
899	    constexpr int BH = 4;  // data block tile height handled by find extrema kernel
900	
901	    // Computational block of threads and grid of blocks used by find extrema (1) and compute descriptors (2) kernels
902	    dim3 compThreads1{128, 1, 1};
903	    dim3 compThreads2{256, 1, 1};
904	    dim3 compBlocks1;
905	    dim3 compBlocks2(maxCapacity, 1, currShape.z);
906	
907	    TensorWrapLNHW<const float> firstDescriptorGauss;
908	    int3                        firstDescriptorShape;
909	    int                         firstDescriptorOctave = 0;
910	    float                       firstDescriptorScale  = 1.f;
911	
912	    cuda::Tensor2DWrap<float4, int32_t> featCoordsWrap(featCoordsData.basePtr(), (int)featCoordsData.stride(0));
913	    cuda::Tensor2DWrap<float3, int32_t> featMetadataWrap(featMetadataData.basePtr(), (int)featMetadataData.stride(0));
914	    cuda::Tensor1DWrap<int, int32_t>    numFeaturesWrap(numFeaturesData.basePtr());
915	    TensorWrapForDescriptor featDescriptorsWrap(featDescriptorsData.basePtr(), (int)featDescriptorsData.stride(0));
916	
917	    // Initially set to zero the number of features for each image within source tensor, currShape.z = # of images
918	    NVCV_CHECK_THROW(cudaMemsetAsync(numFeaturesData.basePtr(), 0, sizeof(int) * currShape.z, stream));
919	
920	    int intThreshold = std::floor(.5f * contrastThreshold / numOctaveLayers * 255);
921	
922	    for (int octave = 0; octave < numOctaves; octave++)
923	    {
924	        // The Gaussian pyramid stores at octave=0 the base (potentially expanded) input image, that is why the
925	        // current Gaussian data is shifted by 1 while DoG (Difference of Gaussians) data is not
926	
927	        auto currGaussData = m_runPyramidGaussian[octave + 1].exportData<nvcv::TensorDataStridedCuda>();
928	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(currGaussData);
929	
930	        auto currDoGData = m_runPyramidDoG[octave].exportData<nvcv::TensorDataStridedCuda>();
931	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(currDoGData);
932	
933	        TensorWrapLNHW<const float> currGaussWrap(*currGaussData);
934	        TensorWrapLNHW<const float> currDoGWrap(*currDoGData);
935	
936	        compBlocks1 = dim3(util::DivUp(currShape.x, BW), util::DivUp(currShape.y, BH), currShape.z);
937	
938	        int   featOctave    = firstOctave + octave; // feature octave may start at -1 base expanded input image
939	        float scaleOctave   = ::pow(2, featOctave); // scale feature coordinate or size back to base image
940	        float unscaleOctave = 1.f / scaleOctave;    // un-scale feature coordinate or size back to current octave
941	
942	        int descriptorOctaveIndex = octave % kDescriptorOctaveBatch;
943	        if (descriptorOctaveIndex == 0)
944	        {
945	            firstDescriptorGauss  = currGaussWrap;
946	            firstDescriptorShape  = currShape;
947	            firstDescriptorOctave = featOctave;
948	            firstDescriptorScale  = unscaleOctave;
949	        }
950	
951	        // First run the DoFindExtrema kernel to find extrema points (the features) and compute their metadata
952	
953	        DoFindExtrema<BW, BH, DT><<<compBlocks1, compThreads1, 0, stream>>>(
954	            featCoordsWrap, featMetadataWrap, maxCapacity, numFeaturesWrap, currGaussWrap, currDoGWrap, currShape,
955	            featOctave, scaleOctave, numOctaveLayers, intThreshold, contrastThreshold, edgeThreshold, initSigma);
956	
957	        if (descriptorOctaveIndex == kDescriptorOctaveBatch - 1 || octave == numOctaves - 1)
958	        {
959	            bool hasSecondOctave = descriptorOctaveIndex == kDescriptorOctaveBatch - 1;
960	
961	            DoComputeDescriptors<<<compBlocks2, compThreads2, 0, stream>>>(
962	                featDescriptorsWrap, featCoordsWrap, featMetadataWrap, numFeaturesWrap, firstDescriptorGauss,
963	                firstDescriptorShape, firstDescriptorOctave, firstDescriptorScale, currGaussWrap, currShape, featOctave,
964	                unscaleOctave, hasSecondOctave);
965	        }
966	
967	        currShape.x /= 2;
968	        currShape.y /= 2;
969	    }
970	}
971	
972	// Compute run-time pyramids, DT is the input data type
973	template<typename DT>
974	void SIFT::ComputePyramids(const nvcv::TensorDataStridedCuda &inData, int3 currShape, bool expandInput, int numOctaves,
975	                           int numOctaveLayers, float initSigma, cudaStream_t stream) const
976	{
977	    constexpr int BW = 32; // data block tile width in shared memory (smem) used by compute pyramids kernel
978	    constexpr int BH = 32; // data block tile height in shared memory (smem) used by compute pyramids kernel
979	
980	    // Block of threads and grid of blocks used by copy and compute pyramid kernels
981	    dim3 copyThreads{256, 1, 1};
982	    dim3 copyBlocks(util::DivUp(currShape.x, copyThreads.x), currShape.y, currShape.z);
983	
984	    dim3 compThreads{256, 1, 1};
985	    dim3 compBlocks;
986	
987	    NVCV_ASSERT((numOctaves + 1) <= (int)m_runPyramidGaussian.size());
988	    NVCV_ASSERT(numOctaves <= (int)m_runPyramidDoG.size());
989	
990	    // Copy inData into base Gaussian pyramid (octave=0), casting from U8 to F32 (and potentially upscaling it)
991	
992	    auto dstBaseData = m_runPyramidGaussian[0].exportData<nvcv::TensorDataStridedCuda>();
993	    CVCUDA_SIFT_INTERNAL_DATA_CHECK(dstBaseData);
994	
995	    TensorWrapLNHW<float> dstBaseWrap(*dstBaseData);
996	
997	    if (expandInput)
998	    {
999	        auto srcBaseWrap = cuda::CreateInterpolationWrapNHW<const DT, kBorderInterp, kInterpUp, int32_t>(inData);
1000	
1001	        UpCopy<<<copyBlocks, copyThreads, 0, stream>>>(dstBaseWrap, srcBaseWrap, currShape); // upscale copy
1002	    }
1003	    else
1004	    {
1005	        auto srcBaseWrap = cuda::CreateTensorWrapNHW<const DT, int32_t>(inData);
1006	
1007	        Copy<<<copyBlocks, copyThreads, 0, stream>>>(dstBaseWrap, srcBaseWrap, currShape); // direct copy
1008	    }
1009	
1010	    // Set sigma scale, current and base sigma for Gaussian filter kernel computation
1011	
1012	    int   sigmaScale = (expandInput ? 4 : 1); // due to source scaled up by 2x in each dimension
1013	    float currSigma  = cuda::sqrt(cuda::max(initSigma * initSigma - kPrevSigma * kPrevSigma * sigmaScale, kMinSigma));
1014	    float baseSigma  = cuda::pow(2.f, 1.f / numOctaveLayers);
1015	
1016	    cuda::math::Vector<float, kMaxKernelSize> gaussSepKernel; // separable Gaussian filter kernel
1017	
1018	    for (int octave = 0; octave < numOctaves; octave++)
1019	    {
1020	        if (octave > 0)
1021	        {
1022	            currSigma = initSigma; // for every octave after first, the current sigma is the initial sigma
1023	        }
1024	
1025	        // Set previous and current octave Gaussian and DoG (Difference of Gaussians) pyramid data
1026	
1027	        auto prevGaussData = m_runPyramidGaussian[octave].exportData<nvcv::TensorDataStridedCuda>();
1028	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(prevGaussData);
1029	
1030	        auto currGaussData = m_runPyramidGaussian[octave + 1].exportData<nvcv::TensorDataStridedCuda>();
1031	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(currGaussData);
1032	
1033	        auto currDoGData = m_runPyramidDoG[octave].exportData<nvcv::TensorDataStridedCuda>();
1034	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(currDoGData);
1035	
1036	        // Using BorderWrap (BW) when border handling is needed and TensorWrap (TW) when not
1037	
1038	        TensorWrapLNHW<float> prevGaussTW(*prevGaussData);
1039	        TensorWrapLNHW<float> currGaussTW(*currGaussData);
1040	        BorderWrapLNHW<float> prevGaussBW(*prevGaussData);
1041	        BorderWrapLNHW<float> currGaussBW(*currGaussData);
1042	        TensorWrapLNHW<float> currDoGTW(*currDoGData);
1043	
1044	        copyBlocks = dim3(util::DivUp(currShape.x, copyThreads.x), currShape.y, currShape.z);
1045	        compBlocks = dim3(util::DivUp(currShape.x, BW), util::DivUp(currShape.y, BH), currShape.z);
1046	
1047	        // For each layer up to numOctaveLayers +3 to have +1 for DoG and +2 for top/bottom neihbors
1048	        for (int layer = 0; layer < numOctaveLayers + 3; layer++)
1049	        {
1050	            if (layer == 0 && octave > 0)
1051	            {
1052	                // First layer of every octave after first skips Gaussian blur and does only a downscale copy
1053	                DownCopy<<<copyBlocks, copyThreads, 0, stream>>>(currGaussTW, prevGaussTW, currShape, numOctaveLayers);
1054	            }
1055	            else
1056	            {
1057	                if (layer > 0)
1058	                {
1059	                    // Update current sigma for every layer after the first
1060	                    float prevSigma  = cuda::pow(baseSigma, (float)(layer - 1)) * initSigma;
1061	                    float totalSigma = baseSigma * prevSigma;
1062	                    currSigma        = std::sqrt(totalSigma * totalSigma - prevSigma * prevSigma);
1063	                }
1064	
1065	                // Compute the separable Gaussian filter kernel for the Gaussian pyramid
1066	                int   ksize    = ComputeGaussianKernelSize(currSigma);
1067	                int   half     = ksize / 2;
1068	                int   smemSize = ((BW + ksize) * (BH + ksize) + BW * (BH + ksize)) * sizeof(float);
1069	                float ss2      = currSigma * currSigma * 2;
1070	                float sp2      = currSigma * cuda::sqrt(M_PI * 2);
1071	                float sum      = 0.f;
1072	
1073	                for (int kx = -half; kx <= half; ++kx)
1074	                {
1075	                    // Compute separable Gaussian function value using its half-equation
1076	                    float w = cuda::exp(-((kx * kx) / ss2)) / sp2;
1077	
1078	                    sum += w;
1079	
1080	                    gaussSepKernel[half + kx] = w;
1081	                }
1082	                for (int kx = -half; kx <= half; ++kx)
1083	                {
1084	                    gaussSepKernel[half + kx] /= sum;
1085	                }
1086	
1087	                // Run the DoComputePyramids kernel to compute the Gaussian and DoG pyramids
1088	
1089	                if (octave == 0 && layer == 0)
1090	                {
1091	                    // Only for the first octave and first layer the base level previous Gaussian data is used
1092	                    DoComputePyramids<BW, BH><<<compBlocks, compThreads, smemSize, stream>>>(
1093	                        prevGaussBW, currGaussTW, currDoGTW, currShape, layer, ksize, gaussSepKernel);
1094	                }
1095	                else
1096	                {
1097	                    // For every other octave and layer the current Gaussian data (border-aware) is used
1098	                    DoComputePyramids<BW, BH><<<compBlocks, compThreads, smemSize, stream>>>(
1099	                        currGaussBW, currGaussTW, currDoGTW, currShape, layer, ksize, gaussSepKernel);
1100	                }
1101	            }
1102	        }
1103	
1104	        currShape.x /= 2;
1105	        currShape.y /= 2;
1106	    }
1107	}
