1109	// Reshape payload-time maxPyramids to submit (or execution) time runPyramids
1110	void SIFT::ReshapePyramids(const int3 &inShape, int numOctaves, int numOctaveLayers) const
1111	{
1112	    // Create shapes converting from int3=WHN and L=octaveLayers to LNHWC or NHWC tensor shapes
1113	    nvcv::TensorShape::ShapeType shapeGaussian{numOctaveLayers + 3, inShape.z, inShape.y, inShape.x, 1};
1114	    nvcv::TensorShape::ShapeType shapeDoG{numOctaveLayers + 2, inShape.z, inShape.y, inShape.x, 1};
1115	    nvcv::TensorShape::ShapeType shapeBase({1, inShape.z, inShape.y, inShape.x, 1});
1116	
1117	    NVCV_ASSERT((numOctaves + 1) <= (int)m_maxPyramidGaussian.size());
1118	    NVCV_ASSERT((numOctaves + 1) <= (int)m_runPyramidGaussian.size());
1119	    NVCV_ASSERT(numOctaves <= (int)m_maxPyramidDoG.size());
1120	    NVCV_ASSERT(numOctaves <= (int)m_runPyramidDoG.size());
1121	
1122	    // The idea is to get a view of a tensor from maxPyramid into runPyramid.  In the 1st reshape pyramid, it will
1123	    // drop the null tensor, which does not deallocate memory.  In the 2nd reshape pyramid, it will drop the tensor
1124	    // view, which also does not deallocate the parent tensor since maxPyramid holds it.
1125	
1126	    {
1127	        auto gpData = m_maxPyramidGaussian[0].exportData<nvcv::TensorDataStridedCuda>();
1128	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(gpData);
1129	
1130	        m_runPyramidGaussian[0] = GetViewFrom(*gpData, shapeBase);
1131	    }
1132	
1133	    for (int octave = 0; octave < numOctaves; octave++)
1134	    {
1135	        auto gpData = m_maxPyramidGaussian[octave + 1].exportData<nvcv::TensorDataStridedCuda>();
1136	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(gpData);
1137	
1138	        m_runPyramidGaussian[octave + 1] = GetViewFrom(*gpData, shapeGaussian);
1139	
1140	        auto dogData = m_maxPyramidDoG[octave].exportData<nvcv::TensorDataStridedCuda>();
1141	        CVCUDA_SIFT_INTERNAL_DATA_CHECK(dogData);
1142	
1143	        m_runPyramidDoG[octave] = GetViewFrom(*dogData, shapeDoG);
1144	
1145	        shapeGaussian[2] /= 2;
1146	        shapeGaussian[3] /= 2;
1147	        shapeDoG[2] /= 2;
1148	        shapeDoG[3] /= 2;
1149	    }
1150	}
