1152	// Allocate (create) the initial SIFT pyramids for maximum shape (run-time is null) (done on operator constructor)
1153	void SIFT::CreatePyramids()
1154	{
1155	    // Tensor LNHWC layout lives within an octave and has L octave levels each of which with NHWC tensors
1156	    constexpr nvcv::TensorLayout TENSOR_LNHWC(NVCVTensorLayout{"LNHWC", 5});
1157	
1158	    // Create shapes converting from int3=WHN and L=octaveLayers to LNHWC tensor shapes
1159	
1160	    // Gaussian pyramid with maxOctaveLayers +3 to have +1 for DoG and +2 for top/bottom neighbors
1161	    // DoG pyramid with maxOctaveLayers +2 for top/bottom neighbors
1162	    // Base level pyramid with 1 layer to store original image (potentially expanded)
1163	
1164	    nvcv::TensorShape::ShapeType shapeGaussian{m_maxOctaveLayers + 3, m_maxShape.z, m_maxShape.y, m_maxShape.x, 1};
1165	    nvcv::TensorShape::ShapeType shapeDoG{m_maxOctaveLayers + 2, m_maxShape.z, m_maxShape.y, m_maxShape.x, 1};
1166	    nvcv::TensorShape::ShapeType shapeBase({1, m_maxShape.z, m_maxShape.y, m_maxShape.x, 1});
1167	
1168	    // Gaussian pyramid has +1 in octaves to have original base image (potentially expanded) at octave=0
1169	
1170	    m_maxPyramidGaussian.reserve(m_maxOctaves + 1);
1171	    m_runPyramidGaussian.reserve(m_maxOctaves + 1);
1172	    m_maxPyramidDoG.reserve(m_maxOctaves);
1173	    m_runPyramidDoG.reserve(m_maxOctaves);
1174	
1175	    // runPyramids store null tensors as they will be replaced by a view of maxPyramids tensors later on
1176	
1177	    m_maxPyramidGaussian.emplace_back(nvcv::TensorShape{shapeBase, TENSOR_LNHWC}, nvcv::TYPE_F32);
1178	    m_runPyramidGaussian.emplace_back(nvcv::Tensor{});
1179	
1180	    for (int octave = 0; octave < m_maxOctaves; octave++)
1181	    {
1182	        m_maxPyramidGaussian.emplace_back(nvcv::TensorShape{shapeGaussian, TENSOR_LNHWC}, nvcv::TYPE_F32);
1183	        m_runPyramidGaussian.emplace_back(nvcv::Tensor{});
1184	
1185	        m_maxPyramidDoG.emplace_back(nvcv::TensorShape{shapeDoG, TENSOR_LNHWC}, nvcv::TYPE_F32);
1186	        m_runPyramidDoG.emplace_back(nvcv::Tensor{});
1187	
1188	        shapeGaussian[2] /= 2;
1189	        shapeGaussian[3] /= 2;
1190	        shapeDoG[2] /= 2;
1191	        shapeDoG[3] /= 2;
1192	    }
1193	}
