1195	// Constructor -----------------------------------------------------------------
1196	
1197	SIFT::SIFT(int3 maxShape, int maxOctaveLayers)
1198	    : m_maxShape{maxShape}
1199	    , m_maxOctaves{ComputeNumberOfOctaves(maxShape.x, maxShape.y)}
1200	    , m_maxOctaveLayers{maxOctaveLayers}
1201	{
1202	    if (maxShape.x < 2 || maxShape.y < 2 || maxShape.z < 1 || maxShape.z > 65535)
1203	    {
1204	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1205	                              "Operator constructor arg. maxShape (W=%d H=%d N=%d) must have W and H >= 2 and N in "
1206	                              "[1, 65535]",
1207	                              maxShape.x, maxShape.y, maxShape.z);
1208	    }
1209	    if (maxOctaveLayers < 1 || maxOctaveLayers > 16)
1210	    {
1211	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1212	                              "Operator constructor arg. maxOctaveLayers=%d must be in [1, 16]", maxOctaveLayers);
1213	    }
1214	
1215	    CreatePyramids();
1216	}
