1218	// Submit ----------------------------------------------------------------------
1219	
1220	void SIFT::operator()(cudaStream_t stream, const nvcv::Tensor &in, const nvcv::Tensor &featCoords,
1221	                      const nvcv::Tensor &featMetadata, const nvcv::Tensor &featDescriptors,
1222	                      const nvcv::Tensor &numFeatures, int numOctaveLayers, float contrastThreshold,
1223	                      float edgeThreshold, float initSigma, NVCVSIFTFlagType flags) const
1224	{
1225	    CVCUDA_NVTX_RANGE("cvcuda::SIFT::operator()[Tensor]");
1226	    // Check each tensor layout, strides, shape and data type if it is conforming to what is expected
1227	
1228	    if (!(in.layout() == nvcv::TENSOR_HWC || in.layout() == nvcv::TENSOR_NHWC || in.layout() == nvcv::TENSOR_CHW
1229	          || in.layout() == nvcv::TENSOR_NCHW))
1230	    {
1231	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1232	                              "Input tensor layout must be HWC, NHWC, CHW or NCHW");
1233	    }
1234	
1235	    auto inData = in.exportData<nvcv::TensorDataStridedCuda>();
1236	    if (!inData)
1237	    {
1238	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input must be a valid CUDA strided tensor");
1239	    }
1240	    if (inData->dtype() != nvcv::TYPE_U8) // The only supported data type is U8
1241	    {
1242	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input tensor dtype must be U8");
1243	    }
1244	
1245	    auto inAccess = nvcv::TensorDataAccessStridedImagePlanar::Create(*inData);
1246	    if (!inAccess)
1247	    {
1248	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input must be a valid image-based tensor");
1249	    }
1250	    if (inAccess->numChannels() > 1 || inAccess->numPlanes() > 1)
1251	    {
1252	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input tensor must have 1 channel and 1 plane");
1253	    }
1254	
1255	    if (inAccess->sampleStride() * inAccess->numSamples() > cuda::TypeTraits<int32_t>::max)
1256	    {
1257	        throw nvcv::Exception(nvcv::Status::ERROR_OVERFLOW, "Input size exceeds %d. Tensor is too large.",
1258	                              cuda::TypeTraits<int32_t>::max);
1259	    }
1260	
1261	    int3 inShape{(int)inAccess->numCols(), (int)inAccess->numRows(), (int)inAccess->numSamples()};
1262	
1263	    bool expandInput = (flags == NVCV_SIFT_USE_EXPANDED_INPUT);
1264	
1265	    if (expandInput)
1266	    {
1267	        inShape.x *= 2;
1268	        inShape.y *= 2;
1269	    }
1270	
1271	    int numOctaves  = ComputeNumberOfOctaves(inShape.x, inShape.y);
1272	    int firstOctave = expandInput ? -1 : 0;
1273	
1274	    if (inShape.x < 2 || inShape.y < 2 || inShape.z < 1 || inShape.x > m_maxShape.x || inShape.y > m_maxShape.y
1275	        || inShape.z > m_maxShape.z)
1276	    {
1277	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1278	                              "Input tensor shape (W=%d H=%d N=%d) must have W and H >= 2 and N >= 1 and be "
1279	                              "smaller than or equal to maxShape (W=%d H=%d N=%d) defined in operator constructor",
1280	                              inShape.x, inShape.y, inShape.z, m_maxShape.x, m_maxShape.y, m_maxShape.z);
1281	    }
1282	
1283	    if (initSigma <= 0)
1284	    {
1285	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Operator call arg. initSigma=%f must be positive",
1286	                              initSigma);
1287	    }
1288	    if (contrastThreshold <= 0)
1289	    {
1290	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Argument contrastThreshold=%f must be positive",
1291	                              contrastThreshold);
1292	    }
1293	    if (edgeThreshold <= 0)
1294	    {
1295	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Argument edgeThreshold=%f must be positive",
1296	                              edgeThreshold);
1297	    }
1298	
1299	    if (numOctaveLayers < 1 || numOctaveLayers > m_maxOctaveLayers)
1300	    {
1301	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1302	                              "Operator call arg. numOctaveLayers=%d must be in [1, %d]", numOctaveLayers,
1303	                              m_maxOctaveLayers);
1304	    }
1305	
1306	    auto featCoordsData = featCoords.exportData<nvcv::TensorDataStridedCuda>();
1307	    if (!featCoordsData)
1308	    {
1309	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1310	                              "Output featCoords must be a valid CUDA strided tensor");
1311	    }
1312	    if (!((featCoordsData->rank() == 3
1313	           && ((featCoordsData->dtype() == nvcv::TYPE_F32 && featCoordsData->shape(2) == 4)
1314	               || (featCoordsData->dtype() == nvcv::TYPE_4F32 && featCoordsData->shape(2) == 1)))
1315	          || (featCoordsData->rank() == 2 && featCoordsData->dtype() == nvcv::TYPE_4F32)))
1316	    {
1317	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1318	                              "Output featCoords must have rank 2 or 3 and 4xF32 or 4F32 data type");
1319	    }
1320	    if (featCoordsData->shape(0) != inShape.z)
1321	    {
1322	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1323	                              "Output featCoords 1st shape must be the same as input tensor number of samples, "
1324	                              "%d != %d",
1325	                              (int)featCoordsData->shape(0), inShape.z);
1326	    }
1327	    if (!(featCoordsData->stride(1) == sizeof(float4)
1328	              && (featCoordsData->rank() == 3
1329	                  && ((featCoordsData->dtype() == nvcv::TYPE_F32 && featCoordsData->stride(2) == sizeof(float))
1330	                      || (featCoordsData->dtype() == nvcv::TYPE_4F32 && featCoordsData->stride(2) == sizeof(float4))))
1331	          || (featCoordsData->rank() == 2)))
1332	    {
1333	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1334	                              "Output featCoords last strides must be packed for 4xF32 data type, stride1=%d",
1335	                              (int)featCoordsData->stride(1));
1336	    }
1337	
1338	    int maxCapacity = featCoordsData->shape(1);
1339	
1340	    auto featMetadataData = featMetadata.exportData<nvcv::TensorDataStridedCuda>();
1341	    if (!featMetadataData)
1342	    {
1343	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1344	                              "Output featMetadata must be a valid CUDA strided tensor");
1345	    }
1346	    if (!((featMetadataData->rank() == 3
1347	           && ((featMetadataData->dtype() == nvcv::TYPE_F32 && featMetadataData->shape(2) == 3)
1348	               || (featMetadataData->dtype() == nvcv::TYPE_3F32 && featMetadataData->shape(2) == 1)))
1349	          || (featMetadataData->rank() == 2 && featMetadataData->dtype() == nvcv::TYPE_3F32)))
1350	    {
1351	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1352	                              "Output featMetadata must have rank 2 or 3 and 3xF32 or 3F32 data type");
1353	    }
1354	    if (featMetadataData->shape(0) != inShape.z)
1355	    {
1356	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1357	                              "Output featMetadata 1st shape must be the same as input tensor number of samples, "
1358	                              "%d != %d",
1359	                              (int)featMetadataData->shape(0), inShape.z);
1360	    }
1361	    if (featMetadataData->shape(1) != maxCapacity)
1362	    {
