1365	                              (int)featMetadataData->shape(1), maxCapacity);
1366	    }
1367	    if (!(featMetadataData->stride(1) == sizeof(float3)
1368	              && (featMetadataData->rank() == 3
1369	                  && ((featMetadataData->dtype() == nvcv::TYPE_F32 && featMetadataData->stride(2) == sizeof(float))
1370	                      || (featMetadataData->dtype() == nvcv::TYPE_3F32
1371	                          && featMetadataData->stride(2) == sizeof(float3))))
1372	          || (featMetadataData->rank() == 2)))
1373	    {
1374	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1375	                              "Output featMetadata last strides must be packed for 3xF32 data type, stride1=%d",
1376	                              (int)featMetadataData->stride(1));
1377	    }
1378	
1379	    auto featDescriptorsData = featDescriptors.exportData<nvcv::TensorDataStridedCuda>();
1380	    if (!featDescriptorsData)
1381	    {
1382	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1383	                              "Output featDescriptors must be a valid CUDA strided tensor");
1384	    }
1385	    if (!(featDescriptorsData->rank() == 3 && featDescriptorsData->dtype() == nvcv::TYPE_U8
1386	          && featDescriptorsData->shape(2) == kDescSize))
1387	    {
1388	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1389	                              "Output featDescriptors must have rank 3, U8 data type and last shape equals %d",
1390	                              kDescSize);
1391	    }
1392	    if (featDescriptorsData->shape(0) != inShape.z)
1393	    {
1394	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1395	                              "Output featDescriptors 1st shape must be the same as input tensor number of samples, "
1396	                              "%d != %d",
1397	                              (int)featDescriptorsData->shape(0), inShape.z);
1398	    }
1399	    if (featDescriptorsData->shape(1) != maxCapacity)
1400	    {
1401	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1402	                              "Output featDescriptors 2nd shape must be the same across output tensors, %d != %d",
1403	                              (int)featDescriptorsData->shape(1), maxCapacity);
1404	    }
1405	    if (!(featDescriptorsData->stride(2) == sizeof(uint8_t)
1406	          && featDescriptorsData->stride(1) == kDescSize * sizeof(uint8_t)))
1407	    {
1408	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1409	                              "Output featDescriptors last strides must be packed with 128 U8 data type, "
1410	                              "stride1=%d stride2=%d",
1411	                              (int)featDescriptorsData->stride(1), (int)featDescriptorsData->stride(2));
1412	    }
1413	
1414	    auto numFeaturesData = numFeatures.exportData<nvcv::TensorDataStridedCuda>();
1415	    if (!numFeaturesData)
1416	    {
1417	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1418	                              "Output numFeatures must be a valid CUDA strided tensor");
1419	    }
