1424	                              "Output numFeatures must have rank 1 or 2 and 1xS32 or S32 data type");
1425	    }
1426	    if (numFeaturesData->shape(0) != inShape.z)
1427	    {
1428	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1429	                              "Output numFeatures 1st shape must be the same as input tensor number of samples, "
1430	                              "%d != %d",
