34	namespace {
35	
36	// Utilities definitions -------------------------------------------------------
37	
38	namespace cuda = nvcv::cuda;
39	namespace util = nvcv::util;
40	
41	constexpr int kIntMax = cuda::TypeTraits<int>::max; // maximum number represented in an int
42	
43	constexpr int kNumThreads = 64; // number of threads per block
44	
45	// Key value pair type used in CUB (CUDA Unbound) sort and reduce-min operations
46	// The idea is to sort or get the minimum by distance (dist) and then by index (idx)
47	struct KeyValueT
48	{
49	    float dist;
50	    int   idx;
51	};
52	
53	// Point class primary template is not intended to be used directly, instead only its partial specializations
54	// (below) are used, where: <T> is the point type, i.e. the tensor type of the set storing the points; <NB> is the
55	// maximum number of bytes hold by the point class as a cache from global memory (GMEM)
56	template<class T, int NB>
57	class PointT;
58	
59	// Point class partial specialization for type T with NB = 0, a fall-through Point class meaning that n-dimensional
60	// points in a set are loaded directly from global memory (GMEM) without caching
61	template<class T>
62	class PointT<T, 0>
63	{
64	public:
65	    static constexpr int  kMaxSize            = 0; // maximum size in bytes of a single point stored by this class
66	    static constexpr bool kPackedHammingWords = false;
67	
68	    __device__ PointT() = default;
69	
70	    inline __device__ void load(cuda::Tensor3DWrap<T> set, int sampleIdx, int setIdx, int numDim)
71	    {
72	        data = set.ptr(sampleIdx, setIdx);
73	    }
74	
75	    inline __device__ T &operator[](int i) const
76	    {
77	        return data[i];
78	    }
79	
80	private:
81	    T *data;
82	};
83	
84	using RT = uint32_t; // resource type used in a cache inside the PointT class below
85	
86	// Point class partial specialization for type T with any NB, meaning that n-dimensional points in a set are loaded
87	// from global memory (GMEM) and stored in a cache (can be registers or local memory or shared memory), thus this
88	// class can only be used by points with up to NB size in bytes, i.e. n * sizeof(T) <= NB
89	template<class T, int NB>
90	class PointT
91	{
92	    static_assert(NB > 0, "Maximum number of bytes capacity in PointT class must be positive");
93	
94	public:
95	    static constexpr int  kMaxSize            = NB; // maximum size in bytes of a single point stored by this class
96	    static constexpr int  kNumElem            = NB / sizeof(RT); // number of elements in array serving as a cache
97	    static constexpr int  kMaxDims            = NB / sizeof(T);  // maximum number of dimensions a single point may have
98	    static constexpr bool kPackedHammingWords = false;
99	
100	    __device__ PointT() = default;
101	
102	    inline __device__ void load(cuda::Tensor3DWrap<T> set, int sampleIdx, int setIdx, int numDim)
103	    {
104	#pragma unroll
105	        for (int i = 0; i < kNumElem && i < util::DivUp(numDim * (int)sizeof(T), (int)sizeof(RT)); ++i)
106	        {
107	            data[i] = *reinterpret_cast<const RT *>(set.ptr(sampleIdx, setIdx, i * (int)(sizeof(RT) / sizeof(T))));
108	        }
109	    }
110	
111	    inline __device__ T &operator[](int i) const
112	    {
113	        return reinterpret_cast<T *>(&data[0])[i];
114	    }
115	
116	private:
117	    RT data[kNumElem];
118	};
119	
120	// Keep each word as a separately named value so the compiler can cache an exact 32-byte descriptor in registers while
121	// computing Hamming distance a word at a time. Indexing a uint32_t array directly makes nvcc spill every cached descriptor.
122	class PackedU8Point32
123	{
124	public:
125	    static constexpr int  kNumElem            = 8;
126	    static constexpr bool kPackedHammingWords = true;
127	
128	    __device__ PackedU8Point32() = default;
129	
130	    inline __device__ void load(cuda::Tensor3DWrap<const uint8_t> set, int sampleIdx, int setIdx, int)
131	    {
132	        const RT *src = reinterpret_cast<const RT *>(set.ptr(sampleIdx, setIdx));
133	        d0            = src[0];
134	        d1            = src[1];
135	        d2            = src[2];
136	        d3            = src[3];
137	        d4            = src[4];
138	        d5            = src[5];
139	        d6            = src[6];
140	        d7            = src[7];
141	    }
142	
143	    inline __device__ uint8_t operator[](int i) const
144	    {
145	        RT value;
146	        switch (i / 4)
147	        {
148	        case 0:
149	            value = d0;
150	            break;
151	        case 1:
152	            value = d1;
153	            break;
154	        case 2:
155	            value = d2;
156	            break;
157	        case 3:
158	            value = d3;
159	            break;
160	        case 4:
161	            value = d4;
162	            break;
163	        case 5:
164	            value = d5;
165	            break;
166	        case 6:
167	            value = d6;
168	            break;
169	        default:
170	            value = d7;
171	        }
172	        return value >> ((i % 4) * 8);
173	    }
174	
175	    template<int I>
176	    inline __device__ RT word() const
177	    {
178	        static_assert(I < kNumElem);
179	        if constexpr (I == 0)
180	            return d0;
181	        else if constexpr (I == 1)
182	            return d1;
183	        else if constexpr (I == 2)
184	            return d2;
185	        else if constexpr (I == 3)
186	            return d3;
187	        else if constexpr (I == 4)
188	            return d4;
189	        else if constexpr (I == 5)
190	            return d5;
191	        else if constexpr (I == 6)
192	            return d6;
193	        else
194	            return d7;
195	    }
196	
197	private:
198	    RT d0, d1, d2, d3, d4, d5, d6, d7;
199	};
200	
201	static_assert(sizeof(PackedU8Point32) == 32);
202	
203	// Is compatible checks if a {numDim}-dimensional point fits in the corresponding Point T class (above)
204	template<typename T, int NB>
205	inline __host__ bool isCompatible(int numDim)
206	{
207	    return (numDim * (int)sizeof(T)) <= NB;
208	}
209	
210	// Get minimum stride is used to check if a {numDim}-dimensional Point of type T smaller than RT (the cache
211	// resource type in PointT class) can be read in steps of RT, allowing overflow after the last T element
212	template<typename T>
213	inline __host__ int getMinStride(int numDim)
214	{
215	    return util::DivUp(numDim * (int)sizeof(T), (int)sizeof(RT)) * (int)sizeof(RT);
216	}
217	
218	// CUDA functions --------------------------------------------------------------
219	
220	// Reduce-min by key a key-value pair for CUB (CUDA Unbound) to do block-wide reduction to minimum in the first thread
221	inline __device__ KeyValueT minkey(const KeyValueT &a, const KeyValueT &b)
222	{
223	    return (a.dist < b.dist || (a.dist == b.dist && a.idx < b.idx)) ? a : b;
224	}
225	
226	// Absolute difference | a - b | for floating-point values
227	template<typename T, class = cuda::Require<std::is_floating_point_v<T>>>
228	inline __device__ T absdiff(T a, T b)
229	{
230	    return cuda::abs(a - b);
231	}
232	
233	// Absolute difference for integral values, computing difference in unsigned types may lead to wrap around
234	template<typename T, class = cuda::Require<std::is_integral_v<T>>>
235	inline __device__ std::make_unsigned_t<T> absdiff(T a, T b)
236	{
237	    return a < b ? b - a : a - b; // wrapping around is fine!
238	}
239	
240	// Compute {distance} between elements {e1} and {e2} from n-dimensional points p1 and p2
241	template<NVCVNormType NORM, typename T>
242	inline __device__ void ComputeDistance(float &distance, const T &e1, const T &e2)
243	{
244	    if constexpr (NORM == NVCV_NORM_HAMMING)
245	    {
246	        distance += __popc(e1 ^ e2);
247	    }
248	    else if constexpr (NORM == NVCV_NORM_L1)
249	    {
250	        distance += absdiff(e1, e2);
251	    }
252	    else
253	    {
254	        static_assert(NORM == NVCV_NORM_L2, "ComputeDistance accepts only HAMMING, L1 or L2 norms");
255	
256	        float d = absdiff(e1, e2);
257	
258	        distance = fma(d, d, distance); // square-root is postponed as not needed to find best matches
259	    }
260	}
261	
262	template<int I = 0, class Point>
263	inline __device__ void ComputeHammingWords(float &distance, const Point &p1, const Point &p2, int numWords)
264	{
265	    if constexpr (I < Point::kNumElem)
266	    {
267	        if (I < numWords)
268	        {
269	            distance += __popc(p1.template word<I>() ^ p2.template word<I>());
270	        }
271	        ComputeHammingWords<I + 1>(distance, p1, p2, numWords);
272	    }
273	}
274	
275	// Sort pairs of (distance, index) one per thread from a fixed point p1 to all points p2 in set2 with numDim
276	// dimensions, each point is an array with numDim elements of source type ST, each set is an array of points, and
277	// the tensor is an array of sets where the sampleIdx selects the current set within it with set2Size points
278	template<NVCVNormType NORM, class Point, class SetWrapper>
279	inline __device__ void SortKeyValue(float &sortedDist, int &sortedIdx, const Point &p1, const SetWrapper &set2,
280	                                    int numDim, int matchesPerPoint, int sampleIdx, int set2Size)
281	{
282	    sortedDist = cuda::TypeTraits<float>::max;
283	    sortedIdx  = -1;
284	
285	    float curDist;
286	    Point p2;
287	
288	    for (int set2Idx = threadIdx.x; set2Idx < set2Size; set2Idx += kNumThreads)
289	    {
290	        p2.load(set2, sampleIdx, set2Idx, numDim);
291	
292	        curDist = 0.f;
293	
294	        if constexpr (NORM == NVCV_NORM_HAMMING && Point::kPackedHammingWords)
295	        {
296	            constexpr int kElemPerWord = sizeof(RT) / sizeof(uint8_t);
297	            int           numWords     = numDim / kElemPerWord;
298	
299	            ComputeHammingWords(curDist, p1, p2, numWords);
300	
301	            for (int i = numWords * kElemPerWord; i < numDim; ++i)
302	            {
303	                ComputeDistance<NORM>(curDist, p1[i], p2[i]);
304	            }
305	        }
306	        else if constexpr (Point::kMaxSize > 0)
307	        {
308	#pragma unroll
309	            for (int i = 0; i < Point::kMaxDims && i < numDim; ++i)
310	            {
311	                ComputeDistance<NORM>(curDist, p1[i], p2[i]);
312	            }
313	        }
314	        else
315	        {
316	            for (int i = 0; i < numDim; ++i)
317	            {
318	                ComputeDistance<NORM>(curDist, p1[i], p2[i]);
319	            }
320	        }
321	
322	        if (curDist < sortedDist)
323	        {
324	            sortedDist = curDist;
325	            sortedIdx  = set2Idx;
326	        }
327	    }
328	
329	    __syncthreads(); // wait for all the threads to complete their local sorted (distance, index) pair
330	
331	    if (matchesPerPoint == 1) // fast path for top-1 sort is reduce minimum
332	    {
333	        using BlockReduce = cub::BlockReduce<KeyValueT, kNumThreads>;
334	
335	        __shared__ typename BlockReduce::TempStorage cubTempStorage;
336	
337	        KeyValueT keyValue{sortedDist, sortedIdx};
338	
339	        KeyValueT minKeyValue = BlockReduce(cubTempStorage).Reduce(keyValue, minkey);
340	
341	        if (threadIdx.x == 0)
342	        {
343	            sortedDist = minKeyValue.dist;
344	            sortedIdx  = minKeyValue.idx;
345	        }
346	    }
347	    else // normal path to get top-N where N > 1 requires block sort
348	    {
349	        using BlockSort = cub::BlockRadixSort<float, kNumThreads, 1, int>;
350	
351	        __shared__ typename BlockSort::TempStorage cubTempStorage;
352	
353	        float keys[1]   = {sortedDist};
354	        int   values[1] = {sortedIdx};
355	
356	        BlockSort(cubTempStorage).Sort(keys, values);
357	
358	        if (threadIdx.x < matchesPerPoint)
359	        {
360	            sortedDist = keys[0];
361	            sortedIdx  = values[0];
362	        }
363	    }
364	}
365	
366	// Write a match of (set1Idx, set2Idx) with (distance) found at matchIdx inside output matches and distances
367	template<NVCVNormType NORM>
368	inline __device__ void WriteMatch(int matchIdx, int set1Idx, int set2Idx, int sampleIdx, float &distance,
369	                                  cuda::Tensor3DWrap<int> matches, cuda::Tensor2DWrap<float> distances)
370	{
371	    *matches.ptr(sampleIdx, matchIdx, 0) = set1Idx;
372	    *matches.ptr(sampleIdx, matchIdx, 1) = set2Idx;
373	
374	    if (distances.ptr(0) != nullptr)
375	    {
376	        if constexpr (NORM == NVCV_NORM_L2)
377	        {
378	            distance = cuda::sqrt(distance); // square-root was postpone for writing time, which is now
379	        }
380	
381	        *distances.ptr(sampleIdx, matchIdx) = distance;
382	    }
383	}
384	
385	// Brute-force matcher finds closest pairs of n-dimensional points in set1 and set2, comparing all against all, it
386	// is instantiated by: <NB> an upper limit of each point size in bytes; <NORM> type; and <ST> source type
387	template<int NB, NVCVNormType NORM, typename ST, class Point = PointT<ST, NB>>
388	__global__ void BruteForceMatcher(cuda::Tensor3DWrap<ST> set1, cuda::Tensor3DWrap<ST> set2,
389	                                  cuda::Tensor1DWrap<const int> numSet1, cuda::Tensor1DWrap<const int> numSet2,
390	                                  cuda::Tensor3DWrap<int> matches, cuda::Tensor1DWrap<int> numMatches,
391	                                  cuda::Tensor2DWrap<float> distances, int set1Capacity, int set2Capacity,
392	                                  int outCapacity, int numDim, bool crossCheck, int matchesPerPoint)
393	{
394	    int sampleIdx = blockIdx.x;
395	    int set1Idx   = blockIdx.y;
396	    int set1Size  = set1Capacity;
397	
398	    if (numSet1.ptr(0) != nullptr)
399	    {
400	        set1Size = numSet1[sampleIdx];
401	        set1Size = set1Size > set1Capacity ? set1Capacity : set1Size;
402	    }
403	
404	    if (set1Idx >= set1Size)
405	    {
406	        return;
407	    }
408	
409	    int set2Size = set2Capacity;
410	
411	    if (numSet2.ptr(0) != nullptr)
412	    {
413	        set2Size = numSet2[sampleIdx];
414	        set2Size = set2Size > set2Capacity ? set2Capacity : set2Size;
415	    }
416	
417	    Point p;
418	
419	    p.load(set1, sampleIdx, set1Idx, numDim);
420	
421	    float dist;
422	    int   set2Idx;
423	
424	    SortKeyValue<NORM>(dist, set2Idx, p, set2, numDim, matchesPerPoint, sampleIdx, set2Size);
425	
426	    if (crossCheck)
427	    {
428	        __shared__ int set2Idx2;
429	
430	        if (threadIdx.x == 0)
431	        {
432	            set2Idx2 = set2Idx;
433	        }
434	
435	        __syncthreads(); // wait the first thread to communicate the best match in set2 index
436	
437	        p.load(set2, sampleIdx, set2Idx2, numDim);
438	
439	        float dist2;
440	        int   set1Idx2;
441	
442	        SortKeyValue<NORM>(dist2, set1Idx2, p, set1, numDim, matchesPerPoint, sampleIdx, set1Size);
443	
444	        if (threadIdx.x == 0 && set1Idx2 == set1Idx)
445	        {
446	            int matchIdx = atomicAdd(numMatches.ptr(sampleIdx), 1);
447	
448	            if (matchIdx < outCapacity)
449	            {
450	                WriteMatch<NORM>(matchIdx, set1Idx, set2Idx, sampleIdx, dist, matches, distances);
451	            }
452	        }
453	    }
454	    else
455	    {
456	        if (threadIdx.x < matchesPerPoint)
457	        {
458	            int matchIdx = set1Idx * matchesPerPoint + threadIdx.x;
459	
460	            if (matchIdx < outCapacity)
461	            {
462	                WriteMatch<NORM>(matchIdx, set1Idx, set2Idx, sampleIdx, dist, matches, distances);
463	            }
464	        }
465	    }
466	}
467	
468	// Write number of matches in the case without cross check this number is set1 size times matches per point
469	__global__ void WriteNumMatches(cuda::Tensor1DWrap<const int> numSet1, cuda::Tensor1DWrap<int> numMatches,
470	                                int set1Capacity, int matchesPerPoint)
471	{
472	    int sampleIdx = blockIdx.x;
473	    int set1Size  = (numSet1.ptr(0) == nullptr) ? set1Capacity : numSet1[sampleIdx];
474	
475	    numMatches[sampleIdx] = set1Size * matchesPerPoint;
476	}
477	
478	// Run functions ---------------------------------------------------------------
479	
480	// Run brute-force matcher, using NORM type for distance calculations and SrcT is the input source data type
481	template<NVCVNormType NORM, typename SrcT>
482	inline void RunBruteForceMatcherForNorm(cudaStream_t stream, const nvcv::Tensor &set1, const nvcv::Tensor &set2,
483	                                        const nvcv::Tensor &numSet1, const nvcv::Tensor &numSet2,
484	                                        const nvcv::Tensor &matches, const nvcv::Tensor &numMatches,
485	                                        const nvcv::Tensor &distances, bool crossCheck, int matchesPerPoint)
486	{
487	    cuda::Tensor3DWrap<const SrcT>    w_set1; // tensor wraps of set1 and set2 and other tensors
488	    cuda::Tensor3DWrap<const SrcT>    w_set2;
489	    cuda::Tensor1DWrap<const int32_t> w_numSet1;
490	    cuda::Tensor1DWrap<const int32_t> w_numSet2;
491	    cuda::Tensor3DWrap<int32_t>       w_matches;
492	    cuda::Tensor1DWrap<int32_t>       w_numMatches;
493	    cuda::Tensor2DWrap<float>         w_distances;
494	
495	#define CVCUDA_BFM_WRAP(TENSOR)                                                                                     \
496	    if (TENSOR)                                                                                                     \
497	    {                                                                                                               \
498	        auto data = TENSOR.exportData<nvcv::TensorDataStridedCuda>();                                               \
499	        if (!data)                                                                                                  \
500	        {                                                                                                           \
501	            throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, #TENSOR " tensor must be cuda-accessible"); \
502	        }                                                                                                           \
503	        w_##TENSOR = decltype(w_##TENSOR)(*data);                                                                   \
504	    }
505	
506	    CVCUDA_BFM_WRAP(set1);
507	    CVCUDA_BFM_WRAP(set2);
508	
509	    CVCUDA_BFM_WRAP(numSet1);
510	    CVCUDA_BFM_WRAP(numSet2);
511	
512	    CVCUDA_BFM_WRAP(matches);
513	    CVCUDA_BFM_WRAP(numMatches);
514	
515	    CVCUDA_BFM_WRAP(distances);
516	
517	#undef CVCUDA_BFM_WRAP
518	
519	    int numSamples   = set1.shape()[0];            // number of samples, where each sample is a set of points
520	    int set1Capacity = set1.shape()[1];            // set capacity is the maximum allowed number of points in set1
521	    int set2Capacity = set2.shape()[1];            // set capacity is the maximum allowed number of points in set2
522	    int numDim       = set1.shape()[2];            // number of dimensions of each n-dimensional point in set1 and set2
523	    int outCapacity  = matches.shape()[1];         // output capacity to store matches and distances
524	    int minStride    = getMinStride<SrcT>(numDim); // minimum stride in sets to allow the usage of PointT class
525	
526	    dim3 threads(kNumThreads, 1, 1);
527	    dim3 blocks1(numSamples, 1, 1);
528	    dim3 blocks2(numSamples, set1Capacity, 1);
529	
530	    if (crossCheck)
531	    {
532	        // Cross check returns a varying number of matches, as a match is only valid if it is the best (closest)
533	        // match from set1 to set2 and back from set2 to set1, the numMatches output starts at zero and is
534	        // atomically incremented in the BruteForceMatcher kernel
535	
536	        NVCV_CHECK_THROW(cudaMemsetAsync(w_numMatches.ptr(0), 0, sizeof(int32_t) * numSamples, stream));
537	    }
538	    else
539	    {
540	        // Without cross check has a fixed number of matches equal to the set1 size, meaning for every point in
541	        // set1 there is (are) one (or more) matche(s) (up to matchesPerPoint) in set2
542	
543	        if (numMatches)
544	        {
545	            WriteNumMatches<<<blocks1, threads, 0, stream>>>(w_numSet1, w_numMatches, set1Capacity, matchesPerPoint);
546	        }
547	    }
548	
549	    // Cache-based kernel specialization: numDim and SrcT must fit a cache in PointT class; it works for 32B and
550	    // 128B descriptors, such as ORB and SIFT.  Even though it has 256 bytes spill loads/stores for NB = 128, it
551	    // still gives almost 2x performance benefit.
552	
553	    // TODO: The caveat of below kernel specializations is that it takes time to compile (~30sec) and it does not
554	    //       cover points bigger than 128B in size, incurring in low performance for big points.  It may be better
555	    //       to use shared memory for those big points, given a certain maximum point dimension, and use threads to
556	    //       compute per element results instead of per point.
557	
558	#define CVCUDA_BFM_RUN(NB)                                                                                      \
559	    BruteForceMatcher<NB, NORM><<<blocks2, threads, 0, stream>>>(                                               \
560	        w_set1, w_set2, w_numSet1, w_numSet2, w_matches, w_numMatches, w_distances, set1Capacity, set2Capacity, \
561	        outCapacity, numDim, crossCheck, matchesPerPoint);                                                      \
562	    return
563	
564	    if (w_set1.strides()[1] >= minStride && w_set2.strides()[1] >= minStride)
565	    {
566	        if (isCompatible<SrcT, 32>(numDim))
567	        {
568	            if constexpr (NORM == NVCV_NORM_HAMMING && std::is_same_v<SrcT, uint8_t>)
569	            {
570	                if (numDim == 32)
571	                {
572	                    BruteForceMatcher<32, NORM, const SrcT, PackedU8Point32><<<blocks2, threads, 0, stream>>>(
573	                        w_set1, w_set2, w_numSet1, w_numSet2, w_matches, w_numMatches, w_distances, set1Capacity,
574	                        set2Capacity, outCapacity, numDim, crossCheck, matchesPerPoint);
575	                    return;
576	                }
577	            }
578	            CVCUDA_BFM_RUN(32);
579	        }
580	        else if (isCompatible<SrcT, 128>(numDim))
581	        {
582	            CVCUDA_BFM_RUN(128);
583	        }
584	    }
585	
586	    CVCUDA_BFM_RUN(0);
587	
588	#undef CVCUDA_BFM_RUN
589	}
590	
591	template<typename SrcT>
592	inline void RunBruteForceMatcherForType(cudaStream_t stream, const nvcv::Tensor &set1, const nvcv::Tensor &set2,
593	                                        const nvcv::Tensor &numSet1, const nvcv::Tensor &numSet2,
594	                                        const nvcv::Tensor &matches, const nvcv::Tensor &numMatches,
595	                                        const nvcv::Tensor &distances, bool crossCheck, int matchesPerPoint,
596	                                        NVCVNormType normType)
597	{
598	    switch (normType)
599	    {
600	    case NVCV_NORM_HAMMING:
601	        if constexpr (std::is_floating_point_v<SrcT>)
602	        {
603	            throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Invalid norm Hamming with float input type");
604	        }
605	        else
606	        {
607	            RunBruteForceMatcherForNorm<NVCV_NORM_HAMMING, SrcT>(stream, set1, set2, numSet1, numSet2, matches,
608	                                                                 numMatches, distances, crossCheck, matchesPerPoint);
609	        }
610	        break;
611	
612	#define CVCUDA_BFM_CASE(NORM)                                                                                         \
613	    case NORM:                                                                                                        \
614	        RunBruteForceMatcherForNorm<NORM, SrcT>(stream, set1, set2, numSet1, numSet2, matches, numMatches, distances, \
615	                                                crossCheck, matchesPerPoint);                                         \
616	        break
617	
618	        CVCUDA_BFM_CASE(NVCV_NORM_L1);
619	        CVCUDA_BFM_CASE(NVCV_NORM_L2);
620	
621	#undef CVCUDA_BFM_CASE
622	
623	    default:
624	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Invalid norm type");
625	    }
626	}
627	
628	inline void RunBruteForceMatcher(cudaStream_t stream, const nvcv::Tensor &set1, const nvcv::Tensor &set2,
629	                                 const nvcv::Tensor &numSet1, const nvcv::Tensor &numSet2, const nvcv::Tensor &matches,
630	                                 const nvcv::Tensor &numMatches, const nvcv::Tensor &distances, bool crossCheck,
631	                                 int matchesPerPoint, NVCVNormType normType)
632	{
633	    switch (static_cast<NVCVDataType>(set1.dtype()))
634	    {
635	#define CVCUDA_BFM_CASE(DT, T)                                                                               \
636	    case static_cast<NVCVDataType>(nvcv::TYPE_##DT):                                                         \
637	        RunBruteForceMatcherForType<T>(stream, set1, set2, numSet1, numSet2, matches, numMatches, distances, \
638	                                       crossCheck, matchesPerPoint, normType);                               \
639	        break
640	
641	        CVCUDA_BFM_CASE(U8, uint8_t);
642	        CVCUDA_BFM_CASE(U32, uint32_t);
643	        CVCUDA_BFM_CASE(F32, float);
644	
645	#undef CVCUDA_BFM_CASE
646	
647	    default:
648	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Invalid input data type");
649	    }
650	}
651	
652	} // anonymous namespace
653	
654	namespace cvcuda::priv {
655	
656	// Constructor -----------------------------------------------------------------
657	
658	PairwiseMatcher::PairwiseMatcher(NVCVPairwiseMatcherType algoChoice)
659	    : m_algoChoice(algoChoice)
660	{
661	    // Support additional algorithms here (only brute force for now), they may require payload
662	    if (algoChoice != NVCV_BRUTE_FORCE)
663	    {
664	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Invalid algorithm choice");
665	    }
666	}
667	
668	// Tensor operator -------------------------------------------------------------
669	
670	void PairwiseMatcher::operator()(cudaStream_t stream, const nvcv::Tensor &set1, const nvcv::Tensor &set2,
671	                                 const nvcv::Tensor &numSet1, const nvcv::Tensor &numSet2, const nvcv::Tensor &matches,
672	                                 const nvcv::Tensor &numMatches, const nvcv::Tensor &distances, bool crossCheck,
673	                                 int matchesPerPoint, NVCVNormType normType)
674	{
675	    CVCUDA_NVTX_RANGE("cvcuda::PairwiseMatcher::operator()[Tensor]");
676	    // Check each input and output tensor and their properties are conforming to what is expected
677	
678	    if (!set1 || !set2 || !matches)
679	    {
680	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Required tensors: set1 set2 matches");
681	    }
682	    if (set1.rank() != 3)
683	    {
684	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input set1 must be a rank-3 tensor");
685	    }
686	    if (set2.rank() != 3)
687	    {
688	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input set2 must be a rank-3 tensor");
689	    }
690	    if (set1.dtype() != set2.dtype())
691	    {
692	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input sets must have the same data type");
693	    }
694	
695	    int64_t numSamples = set1.shape()[0];
696	    int64_t numDim     = set1.shape()[2];
697	
698	    if (set2.shape()[0] != numSamples || set2.shape()[2] != numDim)
699	    {
700	        std::ostringstream oss;
701	        oss << (set2 ? set2.shape() : nvcv::TensorShape());
702	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Invalid set2 shape %s is not [NMD]: N=%ld D=%ld",
703	                              oss.str().c_str(), numSamples, numDim);
704	    }
705	
706	    if (numSamples > kIntMax || numDim > kIntMax || set1.shape()[1] > kIntMax || set2.shape()[1] > kIntMax)
707	    {
708	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Too big input tensors, shape > %d", kIntMax);
709	    }
710	
711	    if (numSet1
712	        && ((numSet1.rank() != 1 && numSet1.rank() != 2) || numSet1.shape()[0] != numSamples
713	            || (numSet1.rank() == 2 && numSet1.shape()[1] != 1) || numSet1.dtype() != nvcv::TYPE_S32))
714	    {
715	        std::ostringstream oss;
716	        oss << numSet1.shape();
717	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
718	                              "Invalid numSet1 shape %s dtype %s are not [N] or [NC]: N=%ld C=1 dtype=S32",
719	                              oss.str().c_str(), nvcvDataTypeGetName(numSet1.dtype()), numSamples);
720	    }
721	
722	    if (numSet2
723	        && ((numSet2.rank() != 1 && numSet2.rank() != 2) || numSet2.shape()[0] != numSamples
724	            || (numSet2.rank() == 2 && numSet2.shape()[1] != 1) || numSet2.dtype() != nvcv::TYPE_S32))
725	    {
726	        std::ostringstream oss;
727	        oss << numSet2.shape();
728	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
729	                              "Invalid numSet2 shape %s dtype %s are not [N] or [NC]: N=%ld C=1 dtype=S32",
730	                              oss.str().c_str(), nvcvDataTypeGetName(numSet2.dtype()), numSamples);
731	    }
732	
733	    if (matches.rank() != 3 || matches.shape()[0] != numSamples || matches.shape()[1] >= kIntMax
734	        || matches.shape()[2] != 2 || matches.dtype() != nvcv::TYPE_S32)
735	    {
736	        std::ostringstream oss;
737	        oss << matches.shape();
738	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
739	                              "Invalid matches shape %s dtype %s are not [NMA]: N=%ld M<%d A=2 dtype=S32",
740	                              oss.str().c_str(), nvcvDataTypeGetName(matches.dtype()), numSamples, kIntMax);
741	    }
742	
743	    if (numMatches
744	        && ((numMatches.rank() != 1 && numMatches.rank() != 2) || numMatches.shape()[0] != numSamples
745	            || (numMatches.rank() == 2 && numMatches.shape()[1] != 1) || numMatches.dtype() != nvcv::TYPE_S32))
746	    {
747	        std::ostringstream oss;
748	        oss << numMatches.shape();
749	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
750	                              "Invalid numMatches shape %s dtype %s are not [N] or [NC]: N=%ld C=1 dtype=S32",
751	                              oss.str().c_str(), nvcvDataTypeGetName(numMatches.dtype()), numSamples);
752	    }
753	
754	    int64_t outCapacity = matches.shape()[1];
755	
756	    if (distances
757	        && ((distances.rank() != 2 && distances.rank() != 3) || distances.shape()[0] != numSamples
758	            || distances.shape()[1] != outCapacity || (distances.rank() == 3 && distances.shape()[2] != 1)
759	            || distances.dtype() != nvcv::TYPE_F32))
760	    {
761	        std::ostringstream oss;
762	        oss << distances.shape();
763	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
764	                              "Invalid distances shape %s dtype %s are not [NM] or [NMC]: N=%ld M=%ld C=1 dtype=S32",
765	                              oss.str().c_str(), nvcvDataTypeGetName(distances.dtype()), numSamples, outCapacity);
766	    }
767	
768	    if (matchesPerPoint <= 0 || matchesPerPoint > kNumThreads)
769	    {
770	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Invalid matchesPerPoint %d is not in [1, %d]",
771	                              matchesPerPoint, kNumThreads);
772	    }
773	    if (crossCheck && matchesPerPoint != 1)
774	    {
775	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
776	                              "Invalid matchesPerPoint %d for crossCheck=true is not 1", matchesPerPoint);
777	    }
778	    if (crossCheck && !numMatches)
779	    {
780	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Invalid numMatches=NULL for crossCheck=true");
781	    }
782	
783	    if (m_algoChoice == NVCV_BRUTE_FORCE)
784	    {
785	        RunBruteForceMatcher(stream, set1, set2, numSet1, numSet2, matches, numMatches, distances, crossCheck,
786	                             matchesPerPoint, normType);
787	    }
788	}
789	
790	} // namespace cvcuda::priv
