1434	inline void RunFindHomography(const nvcv::TensorDataStridedCuda &src, const nvcv::TensorDataStridedCuda &dst,
1435	                              const nvcv::TensorDataStridedCuda &models, const BufferOffsets *bufferOffset,
1436	                              const cuSolver *cusolverData, cudaStream_t stream)
1437	{
1438	    // validation of input data
1439	    if ((src.rank() != 2 && src.rank() != 3) || (dst.rank() != 2 && dst.rank() != 3))
1440	    {
1441	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1442	                              "source and destination points must have rank 2 or 3");
1443	    }
1444	
1445	    if (!(src.shape(0) == dst.shape(0) && src.shape(0) == models.shape(0)))
1446	    {
1447	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1448	                              "source, destination and model must have same batch size");
1449	    }
1450	
1451	    if (src.shape(1) != dst.shape(1))
1452	    {
1453	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1454	                              "source and destination array length must be same length to return a valid model");
1455	    }
1456	
1457	    if (src.shape(1) < 4 || dst.shape(1) < 4)
1458	    {
1459	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1460	                              "source and destination array length must be >=4 to return a valid model");
1461	    }
1462	
1463	    if (!(models.rank() == 3 && models.shape(1) == 3 && models.shape(2) == 3 && models.dtype() == nvcv::TYPE_F32))
1464	    {
1465	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1466	                              "model tensor must be 2D with shape 3x3 and data type F32");
1467	    }
1468	
1469	    if (!((src.rank() == 2 && src.dtype() == nvcv::TYPE_2F32)
1470	          || (src.rank() == 3 && src.dtype() == nvcv::TYPE_F32 && src.shape(2) == 2)))
1471	    {
1472	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1473	                              "source tensor must have data type 2F32 or F32 with last shape 2");
1474	    }
1475	    if (!((dst.rank() == 2 && dst.dtype() == nvcv::TYPE_2F32)
1476	          || (dst.rank() == 3 && dst.dtype() == nvcv::TYPE_F32 && dst.shape(2) == 2)))
1477	    {
1478	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
1479	                              "destination tensor must have data type 2F32 or F32 with last shape 2");
1480	    }
