namespace cvcudapy {

namespace {

using TupleTensor4 = std::tuple<Tensor, Tensor, Tensor, Tensor>;

class PyOpSIFT : public nvcvpy::Container // NOSONAR: operator wrappers share the Python cache hierarchy.
{
public:
    class Key : public nvcvpy::IKey
    {
    public:
        Key(const int3 &maxShape, int maxOctaveLayers)
            : m_maxShape{maxShape}
            , m_maxOctaveLayers{maxOctaveLayers}
        {
        }

        bool canBeUsedWith(const int3 &maxShape, int maxOctaveLayers) const
        {
            return (maxShape.x <= m_maxShape.x && maxShape.y <= m_maxShape.y && maxShape.z <= m_maxShape.z
                    && maxOctaveLayers <= m_maxOctaveLayers);
        }

        long long int payloadSize() const
        {
            return static_cast<long long int>(m_maxShape.x) * m_maxShape.y * m_maxShape.z * m_maxOctaveLayers;
        }

    private:
        size_t doGetHash() const override
        {
            return nvcvpy::util::ComputeHash(m_maxShape);
        }

        bool doIsCompatible(const nvcvpy::IKey &that_) const override
        {
            const auto &that = static_cast<const Key &>(that_);
            return that.canBeUsedWith(m_maxShape, m_maxOctaveLayers);
        }

        int3 m_maxShape;
        int  m_maxOctaveLayers;
    };

    PyOpSIFT(const int3 &maxShape, int maxOctaveLayers)
        : m_key(maxShape, maxOctaveLayers)
        , m_op(maxShape, maxOctaveLayers)
    {
    }

    template<class... AA>
    void submit(AA &&...args)
    {
        m_op(std::forward<AA>(args)...);
    }

    py::object container() const override
    {
        return py::reinterpret_borrow<py::object>(this->ptr());
    }

    const nvcvpy::IKey &key() const override
    {
        return m_key;
    }

    static std::shared_ptr<nvcvpy::ICacheItem> fetch(std::vector<std::shared_ptr<nvcvpy::ICacheItem>> &cache)
    {
        assert(!cache.empty());

        // Find the operator with the largest workspace (can handle any smaller request)
        std::shared_ptr<nvcvpy::ICacheItem> retItem        = cache[0];
        long long int                       maxPayloadSize = 0;

        for (const auto &item : cache)
        {
            const auto &key = static_cast<const Key &>(item.get()->key());

            long long int keyPayloadSize = key.payloadSize();

            if (keyPayloadSize > maxPayloadSize)
            {
                maxPayloadSize = keyPayloadSize;
                retItem        = item;
            }
        }

        // Note: Removed cache.clear() and removeAllNotInUseMatching() calls to reduce per-call overhead.
        // The cache will naturally evict unused operators when memory pressure occurs.
        // This fix matches the pattern used in OpInpaint.cpp.

        return retItem;
    }

private:
    Key          m_key;
    cvcuda::SIFT m_op;
};

// Auxiliary function to get tensor access for input tensor in
auto tensorAccess(Tensor &in)
{
    auto inData = in.exportData<nvcv::TensorDataStridedCuda>();
    if (!inData)
    {
        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input must be a valid CUDA strided tensor");
    }
    auto inAccess = nvcv::TensorDataAccessStridedImagePlanar::Create(*inData);
    if (!inAccess)
    {
        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Input must be a valid image-based tensor");
    }
    return inAccess;
}

TupleTensor4 SIFTInto(Tensor &featCoords, Tensor &featMetadata, Tensor &featDescriptors, Tensor &numFeatures,
                      Tensor &in, int numOctaveLayers, float contrastThreshold, float edgeThreshold, float initSigma,
                      NVCVSIFTFlagType flags, std::optional<Stream> pstream)
{
    if (!pstream)
    {
        pstream = Stream::Current();
    }

    auto inAccess = tensorAccess(in);
    int3 inShape{inAccess->numCols(), inAccess->numRows(), static_cast<int>(inAccess->numSamples())};
    if (flags == NVCV_SIFT_USE_EXPANDED_INPUT)
    {
        inShape.x *= 2;
        inShape.y *= 2;
    }

    auto op = CreateOperatorEx<PyOpSIFT>(inShape, numOctaveLayers);

    ResourceGuard guard(*pstream);
    guard.add(LockMode::LOCK_MODE_READ, {in});
    guard.add(LockMode::LOCK_MODE_WRITE, {featCoords, featMetadata, featDescriptors, numFeatures});
    guard.add(LockMode::LOCK_MODE_READWRITE, {*op});

    guard.run(
        [&op, &pstream, &in, &featCoords, &featMetadata, &featDescriptors, &numFeatures, &numOctaveLayers,
         &contrastThreshold, &edgeThreshold, &initSigma, &flags]()
        {
            op->submit(pstream->cudaHandle(), in, featCoords, featMetadata, featDescriptors, numFeatures,
                       numOctaveLayers, contrastThreshold, edgeThreshold, initSigma, flags);
        });

    return TupleTensor4(std::move(featCoords), std::move(featMetadata), std::move(featDescriptors),
                        std::move(numFeatures));
}

// Get default number of maximum features given width and height (5% of total pixels at a minimum of 1)
inline int GetDefaultMaxFeatures(int width, int height)
{
    return std::max(width * height / 20, 1);
}

TupleTensor4 SIFT(Tensor &in, int maxFeatures, int numOctaveLayers, float contrastThreshold, float edgeThreshold,
                  float initSigma, NVCVSIFTFlagType flags, std::optional<Stream> pstream)
{
    auto inAccess   = tensorAccess(in);
    auto numSamples = static_cast<int>(inAccess->numSamples());

    maxFeatures = maxFeatures == 0 ? GetDefaultMaxFeatures(inAccess->numCols(), inAccess->numRows()) : maxFeatures;

    // Row align must be 1 in below tensors so last 2 dimensions are packed

    // clang-format off

    auto featCoords      = Tensor::Create({{numSamples, maxFeatures, 4}, "NMC"}, nvcv::TYPE_F32, 1);
    auto featMetadata    = Tensor::Create({{numSamples, maxFeatures, 3}, "NMC"}, nvcv::TYPE_F32, 1);
    auto featDescriptors = Tensor::Create({{numSamples, maxFeatures, 128}, "NMD"}, nvcv::TYPE_U8, 1);
    auto numFeatures     = Tensor::Create({{numSamples, 1}, "NC"}, nvcv::TYPE_S32, 1);

    // clang-format on

    return SIFTInto(featCoords, featMetadata, featDescriptors, numFeatures, in, numOctaveLayers, contrastThreshold,
                    edgeThreshold, initSigma, flags, pstream);
}

} // namespace

void ExportOpSIFT(py::module &m)
{
    using namespace pybind11::literals;

    m.def("sift", NvtxTrace("cvcuda.sift", &SIFT), "src"_a, "max_features"_a = 0, "num_octave_layers"_a = 3,
          "contrast_threshold"_a = 0.03f, "edge_threshold"_a = 10.f, "init_sigma"_a = 1.6f,
          "flags"_a = NVCV_SIFT_USE_EXPANDED_INPUT, py::kw_only(), "stream"_a = nullptr, R"pbdoc(
        Executes the SIFT operation on the given cuda stream.


        Args:
            src (cvcuda.Tensor): Input tensor to extract features and compute descriptors from.
            max_features (Number, optional): Maximum number of features to be extracted, default is 5% of total
                                             pixels at a minimum of 1.
            num_octave_layers (Number, optional): Number of octave layers, default is 3.
            contrast_threshold (Number, optional): Contrast threshold, default is 0.03.
            edge_threshold (Number, optional): Edge threshold, default is 10.0.
            init_sigma (Number, optional): Initial sigma, default is 1.6.
            flags (cvcuda.SIFT, optional): Flag to whether to expand the input or not, default is
                                           cvcuda.SIFT.USE_EXPANDED_INPUT.
            stream (cvcuda.Stream, optional): CUDA Stream on which to perform the operation.

        Returns:
            Tuple[cvcuda.Tensor, cvcuda.Tensor, cvcuda.Tensor, cvcuda.Tensor]: A tuple with feature coordinates, metadata, descriptors and
            number of features.

    )pbdoc");

    m.def("sift_into", NvtxTrace("cvcuda.sift_into", &SIFTInto), "feat_coords"_a, "feat_metadata"_a,
          "feat_descriptors"_a, "num_features"_a, "src"_a, "num_octave_layers"_a = 3, "contrast_threshold"_a = 0.03f,
          "edge_threshold"_a = 10.f, "init_sigma"_a = 1.6f, "flags"_a = NVCV_SIFT_USE_EXPANDED_INPUT, py::kw_only(),
          "stream"_a = nullptr, R"pbdoc(
        Executes the SIFT operation on the given cuda stream.


        Args:
            feat_coords (cvcuda.Tensor): Output tensor with feature coordinates.
            feat_metadata (cvcuda.Tensor): Output tensor with feature metadata.
            feat_descriptors (cvcuda.Tensor): Output tensor with feature descriptors.
            num_features (cvcuda.Tensor): Output tensor with number of features.
            src (cvcuda.Tensor): Input tensor to extract features and compute descriptors from.
            num_octave_layers (Number, optional): Number of octave layers, default is 3.
            contrast_threshold (Number, optional): Contrast threshold, default is 0.03.
            edge_threshold (Number, optional): Edge threshold, default is 10.0.
            init_sigma (Number, optional): Initial sigma, default is 1.6.
            flags (cvcuda.SIFT, optional): Flag to whether to expand the input or not, default is
                                           cvcuda.SIFT.USE_EXPANDED_INPUT.
            stream (cvcuda.Stream, optional): CUDA Stream on which to perform the operation.

        Returns:
            Tuple[cvcuda.Tensor, cvcuda.Tensor, cvcuda.Tensor, cvcuda.Tensor]: A tuple with feature coordinates, metadata, descriptors and
            number of features.

    )pbdoc");
}

} // namespace cvcudapy

    int64_t numSamples = set1Shape[0];
    int64_t maxMatches = std::max(set1Shape[1], set2Shape[1]) * matchesPerPoint;

    if (!numMatches.has_value())
    {
        numMatches = crossCheck;
    }

    // clang-format off

    Tensor matches = Tensor::Create({{numSamples, maxMatches, 2}, "NMA"}, nvcv::TYPE_S32);

    std::optional<Tensor> numMatchesTensor;
    std::optional<Tensor> distancesTensor;

    if (*numMatches)
    {
        numMatchesTensor = Tensor::Create({{numSamples}, "N"}, nvcv::TYPE_S32);
    }
    if (distances)
    {
        distancesTensor = Tensor::Create({{numSamples, maxMatches}, "NM"}, nvcv::TYPE_F32);
    }

    // clang-format on

    return PairwiseMatcherInto(matches, numMatchesTensor, distancesTensor, set1, set2, numSet1, numSet2, crossCheck,
                               matchesPerPoint, normType, algoChoice, pstream);
}

} // namespace

void ExportOpPairwiseMatcher(py::module &m)
{
    using namespace pybind11::literals;

    m.def("match", NvtxTrace("cvcuda.match", &PairwiseMatcher), "set1"_a, "set2"_a, "num_set1"_a = nullptr,
          "num_set2"_a = nullptr, "num_matches"_a = nullptr, "distances"_a = false, "cross_check"_a = false,
          "matches_per_point"_a = 1, "norm_type"_a = nullptr, "algo_choice"_a = NVCV_BRUTE_FORCE, py::kw_only(),
          "stream"_a = nullptr, R"pbdoc(
        Executes the Pairwise matcher operation on the given CUDA stream.


        Args:
            set1 (cvcuda.Tensor): Input tensor with 1st set of points.
            set2 (cvcuda.Tensor): Input tensor with 2nd set of points.
            num_set1 (cvcuda.Tensor, optional): Input tensor with number of valid points in the 1st set.  If not provided,
                                         consider the entire set1 containing valid points.
            num_set2 (cvcuda.Tensor, optional): Input tensor with number of valid points in the 2nd set.  If not provided,
                                         consider the entire set2 containing valid points.
            num_matches (bool, optional): Use True to return the number of matches.  If not provided, it is set
                                          to True if crossCheck=True and False otherwise.
            distances (bool, optional): Use True to return the match distances.
            cross_check (bool, optional): Use True to cross check best matches, a best match is only returned if it is
                                          the best match (minimum distance) from 1st set to 2nd set and vice versa.
            matches_per_point (Number, optional): Number of best matches to return per point.
            norm_type (cvcuda.Norm, optional): Choice on how distances are normalized.  Defaults to cvcuda.Norm.L2.
            algo_choice (cvcuda.Matcher, optional): Choice of the algorithm to perform the match.
            stream (cvcuda.Stream, optional): CUDA Stream on which to perform the operation.

        Returns:
            Tuple[cvcuda.Tensor, cvcuda.Tensor, cvcuda.Tensor]: A tuple with output matches, number of matches and their distances.
                                           The number of matches tensor may be None if its argument is False.
                                           The distances tensor may be None if its argument is False.

    )pbdoc");

    m.def("match_into", NvtxTrace("cvcuda.match_into", &PairwiseMatcherInto), "matches"_a, "num_matches"_a = nullptr,
          "distances"_a = nullptr, "set1"_a, "set2"_a, "num_set1"_a = nullptr, "num_set2"_a = nullptr,
          "cross_check"_a = false, "matches_per_point"_a = 1, "norm_type"_a = nullptr,
          "algo_choice"_a = NVCV_BRUTE_FORCE, py::kw_only(), "stream"_a = nullptr,
          R"pbdoc(
        Executes the Pairwise matcher operation on the given CUDA stream.


        Args:
            matches (cvcuda.Tensor): Output tensor with matches.
            num_matches (cvcuda.Tensor, optional): Output tensor with number of matches.
            distances (cvcuda.Tensor, optional): Output tensor with match distances.
            set1 (cvcuda.Tensor): Input tensor with 1st set of points.
            set2 (cvcuda.Tensor): Input tensor with 2nd set of points.
            num_set1 (cvcuda.Tensor, optional): Input tensor with number of valid points in the 1st set.  If not provided,
                                         consider the entire set1 containing valid points.
            num_set2 (cvcuda.Tensor, optional): Input tensor with number of valid points in the 2nd set.  If not provided,
                                         consider the entire set2 containing valid points.
            cross_check (bool, optional): Use True to cross check best matches, a best match is only returned if it is
                                          the best match (minimum distance) from 1st set to 2nd set and vice versa.
            matches_per_point (Number, optional): Number of best matches to return per point.
            norm_type (cvcuda.Norm, optional): Choice on how distances are normalized.  Defaults to cvcuda.Norm.L2.
            algo_choice (cvcuda.Matcher, optional): Choice of the algorithm to perform the match.
            stream (cvcuda.Stream, optional): CUDA Stream on which to perform the operation.

        Returns:
            Tuple[cvcuda.Tensor, cvcuda.Tensor, cvcuda.Tensor]: A tuple with output matches, number of matches and their distances.
                                           The number of matches tensor may be None if its argument is None.
                                           The distances tensor may be None if its argument is None.

    )pbdoc");
}

} // namespace cvcudapy

