40	// Specialized Python wrapper for cvcuda::FindHomography.
41	// The underlying DeviceState allocates device buffers sized for
42	// (batchSize, maxNumPoints); a cached op can only be reused when the
43	// request matches those dimensions exactly, otherwise RunFindHomography
44	// would issue memsets and kernel launches past the end of the
45	// allocations. The cache key therefore uses strict equality on both
46	// ctor arguments (matching the generic PyOperator pattern).
47	class PyOpFindHomography : public nvcvpy::Container // NOSONAR: operator wrappers share the Python cache hierarchy.
48	{
49	public:
50	    class Key : public nvcvpy::IKey
51	    {
52	    public:
53	        Key(int batchSize, int maxNumPoints)
54	            : m_batchSize(batchSize)
55	            , m_maxNumPoints(maxNumPoints)
56	        {
57	        }
58	
59	    private:
60	        size_t doGetHash() const override
61	        {
62	            return nvcvpy::util::ComputeHash(m_batchSize, m_maxNumPoints);
63	        }
64	
65	        bool doIsCompatible(const nvcvpy::IKey &that_) const override
66	        {
67	            const auto &that = static_cast<const Key &>(that_);
68	            return m_batchSize == that.m_batchSize && m_maxNumPoints == that.m_maxNumPoints;
69	        }
70	
71	        int m_batchSize;
72	        int m_maxNumPoints;
73	    };
74	
75	    PyOpFindHomography(int batchSize, int maxNumPoints)
76	        : m_key(batchSize, maxNumPoints)
77	        , m_op(batchSize, maxNumPoints)
78	    {
79	    }
80	
81	    inline void submit(cudaStream_t stream, const nvcv::Tensor &srcPts, const nvcv::Tensor &dstPts,
82	                       const nvcv::Tensor &models) const
83	    {
84	        m_op(stream, srcPts, dstPts, models);
85	    }
86	
87	    inline void submit(cudaStream_t stream, const nvcv::TensorBatch &srcPts, const nvcv::TensorBatch &dstPts,
88	                       const nvcv::TensorBatch &models) const
89	    {
90	        m_op(stream, srcPts, dstPts, models);
91	    }
92	
93	    py::object container() const override
94	    {
95	        return py::reinterpret_borrow<py::object>(this->ptr());
96	    }
97	
98	    const nvcvpy::IKey &key() const override
99	    {
100	        return m_key;
101	    }
102	
103	    // Items returned by Cache::fetch have already passed the strict-equality check above,
104	    // so any one of them can serve the request.
105	    static std::shared_ptr<nvcvpy::ICacheItem> fetch(std::vector<std::shared_ptr<nvcvpy::ICacheItem>> &cache)
106	    {
107	        assert(!cache.empty());
108	        return cache[0];
109	    }
110	
111	private:
112	    Key                    m_key;
113	    cvcuda::FindHomography m_op;
114	};
