117	
118	Tensor FindHomographyInto(Tensor &models, Tensor &srcPts, Tensor &dstPts, std::optional<Stream> pstream)
119	{
120	    if (!pstream)
121	    {
122	        pstream = Stream::Current();
123	    }
124	
125	    // Use CreateOperatorEx to use the extended create operator function passing the specialized PyOperator above
126	    // as template type, instead of the regular cvcuda::OP class used in the CreateOperator function.
127	    auto batchSize = static_cast<int32_t>(srcPts.shape()[0]);
128	    auto numPoints = static_cast<int32_t>(srcPts.shape()[1]);
129	
130	    auto findHomography = CreateOperatorEx<PyOpFindHomography>(batchSize, numPoints);
131	
132	    ResourceGuard guard(*pstream);
133	    guard.add(LockMode::LOCK_MODE_READ, {srcPts});
134	    guard.add(LockMode::LOCK_MODE_READ, {dstPts});
135	    guard.add(LockMode::LOCK_MODE_READWRITE, {models});
136	    guard.add(LockMode::LOCK_MODE_READWRITE, {*findHomography});
137	
138	    guard.run([&findHomography, &pstream, &srcPts, &dstPts, &models]()
139	              { findHomography->submit(pstream->cudaHandle(), srcPts, dstPts, models); });
140	
141	    return models;
142	}
143	
144	Tensor FindHomography(Tensor &srcPts, Tensor dstPts, std::optional<Stream> pstream)
145	{
146	    Shape modelsShape(3);
147	    modelsShape[0] = srcPts.shape()[0];
148	    modelsShape[1] = 3;
149	    modelsShape[2] = 3;
150	
151	    Tensor models = Tensor::Create(modelsShape, nvcv::TYPE_F32, nvcv::TENSOR_NHW);
152	
153	    return FindHomographyInto(models, srcPts, dstPts, pstream);
154	}
155	
156	TensorBatch VarShapeFindHomographyInto(TensorBatch &models, TensorBatch &srcPts, TensorBatch &dstPts,
157	                                       std::optional<Stream> pstream)
158	{
159	    if (!pstream)
160	    {
161	        pstream = Stream::Current();
162	    }
163	
164	    // The same PyOpFindHomography class and CreateOperatorEx function can be used regardless of Tensors or VarShape.
165	    int batchSize    = srcPts.numTensors();
166	    int maxNumPoints = 0;
167	
168	    for (int i = 0; i < batchSize; i++)
169	    {
170	        auto numPoints = static_cast<int>(srcPts[i].shape()[1]);
171	        if (numPoints > maxNumPoints)
172	            maxNumPoints = numPoints;
173	    }
174	
175	    auto findHomography = CreateOperatorEx<PyOpFindHomography>(batchSize, maxNumPoints);
176	
177	    ResourceGuard guard(*pstream);
178	    guard.add(LockMode::LOCK_MODE_READ, {srcPts});
179	    guard.add(LockMode::LOCK_MODE_READ, {dstPts});
180	    guard.add(LockMode::LOCK_MODE_READWRITE, {models});
181	    guard.add(LockMode::LOCK_MODE_READWRITE, {*findHomography});
182	
183	    guard.run([&findHomography, &pstream, &srcPts, &dstPts, &models]()
184	              { findHomography->submit(pstream->cudaHandle(), srcPts, dstPts, models); });
185	
186	    return models;
187	}
188	
189	TensorBatch VarShapeFindHomography(TensorBatch &srcPts, TensorBatch &dstPts, std::optional<Stream> pstream)
190	{
191	    TensorBatch models = TensorBatch::Create(srcPts.numTensors());
192	
193	    Shape modelsShape(3);
194	    modelsShape[0] = 1;
195	    modelsShape[1] = 3;
196	    modelsShape[2] = 3;
197	
198	    for (int i = 0; i < srcPts.numTensors(); i++)
199	    {
200	        Tensor outTensor = Tensor::Create(modelsShape, nvcv::TYPE_F32, nvcv::TENSOR_NHW);
201	        models.pushBackTensor(outTensor);
202	    }
203	
204	    return VarShapeFindHomographyInto(models, srcPts, dstPts, pstream);
205	}
