207	// Get a reusable FindHomography operator that can be passed to findhomography_into_with_op.
208	// This allows the caller to hold a persistent reference to prevent cache eviction overhead.
209	// Returns a PyCapsule containing the shared_ptr to the operator.
210	py::object GetFindHomographyOperator(int32_t batchSize, int32_t numPoints)
211	{
212	    auto op = CreateOperatorEx<PyOpFindHomography>(batchSize, numPoints);
213	    // Store the shared_ptr on the heap so it can be held by the capsule.
214	    auto opPtr = std::make_unique<std::shared_ptr<PyOpFindHomography>>(std::move(op));
215	    return py::capsule(opPtr.release(), "FindHomographyOperator",
216	                       [](PyObject *capsule)
217	                       {
218	                           auto ptr = PyCapsule_GetPointer(capsule, "FindHomographyOperator");
219	                           std::unique_ptr<std::shared_ptr<PyOpFindHomography>> opPtr(
220	                               static_cast<std::shared_ptr<PyOpFindHomography> *>(ptr));
221	                           (void)opPtr;
222	                       });
223	}
224	
225	// Version of FindHomographyInto that accepts a pre-fetched operator.
226	// This avoids the cache lookup and ResourceGuard overhead that causes bimodal timing.
227	Tensor FindHomographyIntoWithOp(Tensor &models, Tensor &srcPts, Tensor &dstPts, py::capsule pyOp,
228	                                std::optional<Stream> pstream)
229	{
230	    if (!pstream)
231	    {
232	        pstream = Stream::Current();
233	    }
234	
235	    // Extract the shared_ptr from the capsule
236	    const auto *opPtr          = static_cast<std::shared_ptr<PyOpFindHomography> *>(pyOp.get_pointer());
237	    auto        findHomography = *opPtr;
238	
239	    ResourceGuard guard(*pstream);
240	    guard.add(LockMode::LOCK_MODE_READ, {srcPts});
241	    guard.add(LockMode::LOCK_MODE_READ, {dstPts});
242	    guard.add(LockMode::LOCK_MODE_READWRITE, {models});
243	    // NOTE: Do NOT add findHomography to ResourceGuard - the caller holds the reference
244	
245	    guard.run([&findHomography, &pstream, &srcPts, &dstPts, &models]()
246	              { findHomography->submit(pstream->cudaHandle(), srcPts, dstPts, models); });
247	
248	    return models;
249	}
250	
