300	
301	    )pbdoc");
302	
303	    m.def("findhomography_into", NvtxTrace("cvcuda.findhomography_into", &VarShapeFindHomographyInto), "models"_a,
304	          "srcPts"_a, "dstPts"_a, "stream"_a = nullptr,
305	          R"pbdoc(
306	        Executes the Find Homography operation on the given cuda stream.
307	
308	
309	        Args:
310	            models (cvcuda.TensorBatch): Output model tensor containing 3x3 homography matrices.
311	            srcPts (cvcuda.TensorBatch): Input source coordinates tensor containing 2D coordinates in the source image.
312	            dstPts (cvcuda.TensorBatch): Input destination coordinates tensor containing 2D coordinates in the target image.
313	            stream (cvcuda.Stream, optional): CUDA Stream on which to perform the operation.
314	
315	        Returns:
316	            cvcuda.TensorBatch: The model homography matrix tensor batch.
317	
318	
319	    )pbdoc");
320	
321	    m.def("get_findhomography_operator", NvtxTrace("cvcuda.get_findhomography_operator", &GetFindHomographyOperator),
322	          "batch_size"_a, "num_points"_a, R"pbdoc(
323	        Get a reusable FindHomography operator for the given dimensions.
